tool_schemas.implementation:
def coingecko_get_coin_price_detailed(coin_id, vs_currencies=None, include_market_cap=None, include_24hr_vol=None, include_24hr_change=None, include_last_updated_at=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "coingecko_get_coin_price_detailed"
    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _stable_hash(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _log(status, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        logs.append({
            "id": "req_" + _stable_hash(f"{endpoint}|{now.isoformat()}|{len(logs)}")[:24],
            "endpoint": endpoint,
            "tool_name": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now.isoformat(),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Best-effort global rate limit 240/min using request_logs if present
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        now = _now_utc()
        cutoff = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in reversed(logs[-5000:]):
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts < cutoff:
                break
            recent += 1
        if recent >= 240:
            _log("error", meta={"error_code": "RATE_LIMIT"})
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")

    # Validate inputs
    if not isinstance(coin_id, str) or not coin_id.strip():
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "coin_id must be a non-empty string")

    if vs_currencies is None:
        vs_list = ["usd"]
    elif isinstance(vs_currencies, str):
        if not vs_currencies.strip():
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "vs_currencies must be a non-empty string or an array of strings")
        vs_list = [vs_currencies.strip()]
    elif isinstance(vs_currencies, list):
        vs_list = []
        for v in vs_currencies:
            if not isinstance(v, str) or not v.strip():
                _log("error", meta={"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "vs_currencies must be a string or an array of non-empty strings")
            vs_list.append(v.strip())
        if not vs_list:
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "vs_currencies must contain at least one currency")
    else:
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "vs_currencies must be a string or an array of strings")

    def _bool_default(v, dflt):
        if v is None:
            return dflt
        return v

    include_market_cap = _bool_default(include_market_cap, False)
    include_24hr_vol = _bool_default(include_24hr_vol, False)
    include_24hr_change = _bool_default(include_24hr_change, False)
    include_last_updated_at = _bool_default(include_last_updated_at, False)

    for nm, val in [
        ("include_market_cap", include_market_cap),
        ("include_24hr_vol", include_24hr_vol),
        ("include_24hr_change", include_24hr_change),
        ("include_last_updated_at", include_last_updated_at),
    ]:
        if not isinstance(val, bool):
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", f"{nm} must be a boolean")

    coin_id_n = coin_id.strip().lower()
    vs_norm = [v.strip().lower() for v in vs_list]

    # Resolve coin_id -> asset_id if possible (but do not require it)
    assets = _load("assets.json")
    asset_rows = assets if isinstance(assets, list) else (assets.get("rows") if isinstance(assets, dict) else [])
    asset_rows = asset_rows if isinstance(asset_rows, list) else []
    asset = None
    for a in asset_rows:
        if not isinstance(a, dict):
            continue
        pid = a.get("provider_ids") if isinstance(a.get("provider_ids"), dict) else {}
        if isinstance(pid, dict) and isinstance(pid.get("coingecko_coin_id"), str) and pid.get("coingecko_coin_id").strip().lower() == coin_id_n:
            asset = a
            break

    # Try to serve from cache_entries (cache_type='prices') if valid + not expired
    cache_entries = _load("cache_entries.json")
    cache_rows = cache_entries if isinstance(cache_entries, list) else (cache_entries.get("rows") if isinstance(cache_entries, dict) else [])
    cache_rows = cache_rows if isinstance(cache_rows, list) else []

    tool_name = endpoint
    key_material = json.dumps({
        "coin_id": coin_id_n,
        "vs_currencies": sorted(vs_norm),
        "include_market_cap": include_market_cap,
        "include_24hr_vol": include_24hr_vol,
        "include_24hr_change": include_24hr_change,
        "include_last_updated_at": include_last_updated_at,
    }, sort_keys=True, separators=(",", ":"))
    cache_key = _stable_hash(f"{tool_name}|{key_material}")

    now = _now_utc()
    cached = None
    for ce in cache_rows:
        if not isinstance(ce, dict):
            continue
        if ce.get("cache_type") != "prices":
            continue
        if ce.get("tool_name") != tool_name:
            continue
        if ce.get("key") != cache_key:
            continue
        if ce.get("status") != "valid":
            continue
        exp = _parse_dt(ce.get("expires_at"))
        if exp is not None and exp <= now:
            continue
        cached = ce
        break

    if cached is not None:
        # Update hit counters
        cached["hit_count"] = int(cached.get("hit_count") or 0) + 1
        cached["last_hit_at"] = now.isoformat()
        cached["updated_at"] = now.isoformat()
        _save("cache_entries.json", cache_rows)
        payload = cached.get("payload") if isinstance(cached.get("payload"), dict) else {}
        _log("ok", meta={"cache": "hit", "cache_entry_id": cached.get("id")})
        return {
            "coin_id": coin_id_n,
            "vs_currencies": vs_norm,
            "from_cache": True,
            "data": payload
        }

    # Build response from latest timeseries_points (no error if missing; return empty map)
    points = _load("timeseries_points.json")
    tsp_rows = points if isinstance(points, list) else (points.get("rows") if isinstance(points, dict) else [])
    tsp_rows = tsp_rows if isinstance(tsp_rows, list) else []

    data = {}
    # CoinGecko endpoint returns data keyed by coin_id; we return a coin_id-level map of vs currency fields.
    # Use internal store: latest asset_price for each vs currency; optionally supplement from aux.
    for vs in vs_norm:
        best = None
        best_ts = None
        if asset is not None:
            aid = asset.get("id")
            for p in tsp_rows:
                if not isinstance(p, dict):
                    continue
                if p.get("series_type") != "asset_price":
                    continue
                if p.get("asset_id") != aid:
                    continue
                if (p.get("quote_currency") or "").strip().lower() != vs:
                    continue
                if not isinstance(p.get("value"), (int, float)):
                    continue
                ts = _parse_dt(p.get("bucket_start_at")) or _parse_dt(p.get("updated_at")) or _parse_dt(p.get("created_at"))
                if ts is None:
                    continue
                if best_ts is None or ts > best_ts:
                    best_ts = ts
                    best = p
        # If we can't link via asset, we still return empty for that vs currency (no NOT_FOUND)
        if best is None:
            continue
        entry = {vs: float(best["value"])}
        aux = best.get("aux") if isinstance(best.get("aux"), dict) else {}
        if include_market_cap:
            # coingecko field name is "<vs>_market_cap"
            mc = aux.get("market_cap_usd") if vs == "usd" else aux.get(f"market_cap_{vs}")
            if isinstance(mc, (int, float)):
                entry[f"{vs}_market_cap"] = float(mc)
        if include_24hr_vol:
            vol = aux.get("volume_usd") if vs == "usd" else aux.get(f"volume_{vs}")
            if isinstance(vol, (int, float)):
                entry[f"{vs}_24h_vol"] = float(vol)
        if include_24hr_change:
            ch = aux.get("change_24h_pct")
            if isinstance(ch, (int, float)):
                entry[f"{vs}_24h_change"] = float(ch)
        if include_last_updated_at:
            # coingecko returns epoch seconds; store has iso; convert if available
            if best_ts is not None:
                entry["last_updated_at"] = int(best_ts.timestamp())
        data[vs] = entry

    # Cache the response (short TTL e.g. 60s) to reflect "current price"
    expires = now + datetime.timedelta(seconds=60)
    payload = {}
    # CoinGecko style response is usually: {coin_id: {usd: price, usd_market_cap:..., last_updated_at:...}}
    # We'll store a merged structure keyed by coin_id for easier retrieval.
    merged = {}
    for vs in vs_norm:
        if vs in data:
            merged.update(data[vs])
    payload = {coin_id_n: merged}

    # Upsert cache entry
    existing = None
    for ce in cache_rows:
        if not isinstance(ce, dict):
            continue
        if ce.get("cache_type") == "prices" and ce.get("tool_name") == tool_name and ce.get("key") == cache_key:
            existing = ce
            break

    def _new_id(prefix):
        return prefix + _stable_hash(f"{prefix}|{now.isoformat()}|{time.time_ns()}")[:24]

    if existing is None:
        new_row = {
            "id": _new_id("scry_cch_"),
            "cache_type": "prices",
            "key": cache_key,
            "tool_name": tool_name,
            "normalized_params": {
                "coin_id": coin_id_n,
                "vs_currencies": sorted(vs_norm),
                "include_market_cap": include_market_cap,
                "include_24hr_vol": include_24hr_vol,
                "include_24hr_change": include_24hr_change,
                "include_last_updated_at": include_last_updated_at,
            },
            "payload": payload,
            "expires_at": expires.isoformat(),
            "last_hit_at": now.isoformat(),
            "hit_count": 0,
            "compute_ms": int((time.time() - t0) * 1000),
            "status": "valid" if payload.get(coin_id_n) else "error",
            "created_at": now.isoformat(),
            "updated_at": now.isoformat(),
        }
        cache_rows.append(new_row)
    else:
        existing["normalized_params"] = {
            "coin_id": coin_id_n,
            "vs_currencies": sorted(vs_norm),
            "include_market_cap": include_market_cap,
            "include_24hr_vol": include_24hr_vol,
            "include_24hr_change": include_24hr_change,
            "include_last_updated_at": include_last_updated_at,
        }
        existing["payload"] = payload
        existing["expires_at"] = expires.isoformat()
        existing["compute_ms"] = int((time.time() - t0) * 1000)
        existing["status"] = "valid" if payload.get(coin_id_n) else "error"
        existing["updated_at"] = now.isoformat()

    _save("cache_entries.json", cache_rows)
    _log("ok", meta={"cache": "miss_fill", "has_data": bool(payload.get(coin_id_n))})
    return {
        "coin_id": coin_id_n,
        "vs_currencies": vs_norm,
        "from_cache": False,
        "data": payload
    }

def coingecko_get_market_chart_detailed(coin_id, vs_currency=None, days=None, interval=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "coingecko_get_market_chart_detailed"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _stable_hash(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _log(status, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        row = {
            "id": "req_" + _stable_hash(f"{endpoint}|{now.isoformat()}|{len(logs)}")[:16],
            "endpoint": endpoint,
            "tool_name": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now.isoformat(),
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Rate limit best-effort 240/min global
    try:
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            now = _now_utc()
            cutoff = now - datetime.timedelta(seconds=60)
            recent = 0
            for r in reversed(logs[-5000:]):
                ts = _parse_dt(r.get("timestamp"))
                if not ts:
                    continue
                if ts < cutoff:
                    break
                recent += 1
            if recent >= 240:
                _log("error", meta={"error_code": "RATE_LIMIT"})
                return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
    except Exception:
        pass

    # Validation
    if not isinstance(coin_id, str) or not coin_id.strip():
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "coin_id is required and must be a non-empty string")
    coin_id_n = coin_id.strip().lower()

    if vs_currency is None:
        vs_currency_n = "usd"
    else:
        if not isinstance(vs_currency, str) or not vs_currency.strip():
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "vs_currency must be a non-empty string when provided")
        vs_currency_n = vs_currency.strip().lower()

    # days normalization (CoinGecko accepts number or 'max')
    if days is None:
        days_n = 1
    else:
        if isinstance(days, bool):
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "days must be a number or 'max'")
        if isinstance(days, (int, float)):
            if days <= 0:
                _log("error", meta={"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "days must be > 0 or 'max'")
            days_n = float(days)
        elif isinstance(days, str):
            d = days.strip().lower()
            if d == "max":
                days_n = "max"
            else:
                try:
                    dv = float(d)
                except Exception:
                    _log("error", meta={"error_code": "VALIDATION_ERROR"})
                    return _err("VALIDATION_ERROR", "days must be a number or 'max'")
                if dv <= 0:
                    _log("error", meta={"error_code": "VALIDATION_ERROR"})
                    return _err("VALIDATION_ERROR", "days must be > 0 or 'max'")
                days_n = dv
        else:
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "days must be a number or 'max'")

    # interval: schema says string, but broken calls passed an asset_id; accept unknown strings by treating as "auto"
    interval_n = None
    if interval is not None:
        if not isinstance(interval, str) or not interval.strip():
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "interval must be a non-empty string when provided")
        iv = interval.strip().lower()
        if iv in ("daily", "hourly", "auto"):
            interval_n = iv
        else:
            # Relaxed: treat as auto instead of rejecting, to match real API permissiveness and audit requirement
            interval_n = "auto"

    # Resolve asset by coingecko_coin_id when possible (for backfill)
    assets = _load("assets.json")
    if not isinstance(assets, list):
        assets = []
    asset_row = None
    for a in assets:
        if not isinstance(a, dict):
            continue
        pid = a.get("provider_ids") or {}
        if isinstance(pid, dict) and isinstance(pid.get("coingecko_coin_id"), str) and pid.get("coingecko_coin_id").strip().lower() == coin_id_n:
            asset_row = a
            break
    asset_id = asset_row.get("id") if isinstance(asset_row, dict) else None

    # Cache lookup
    cache_entries = _load("cache_entries.json")
    if not isinstance(cache_entries, list):
        cache_entries = []
    normalized_params = {
        "coin_id": coin_id_n,
        "vs_currency": vs_currency_n,
        "days": days_n,
        "interval": interval_n
    }
    key_material = json.dumps(normalized_params, sort_keys=True, separators=(",", ":"))
    cache_key = hashlib.sha256((endpoint + "|" + key_material).encode("utf-8")).hexdigest()
    now = _now_utc()

    def _is_cache_usable(row):
        if not isinstance(row, dict):
            return False
        if row.get("cache_type") != "prices":
            return False
        if row.get("tool_name") != endpoint:
            return False
        if row.get("key") != cache_key:
            return False
        if row.get("status") != "valid":
            return False
        exp = _parse_dt(row.get("expires_at"))
        if exp is not None and exp <= now:
            return False
        return True

    for ce in cache_entries:
        if _is_cache_usable(ce):
            ce["last_hit_at"] = now.isoformat()
            try:
                ce["hit_count"] = int(ce.get("hit_count") or 0) + 1
            except Exception:
                ce["hit_count"] = 1
            ce["updated_at"] = now.isoformat()
            _save("cache_entries.json", cache_entries)
            payload = ce.get("payload")
            if isinstance(payload, dict):
                _log("ok", meta={"cache_hit": True})
                return payload
            ce["status"] = "error"
            ce["updated_at"] = now.isoformat()
            _save("cache_entries.json", cache_entries)
            break

    # Build response from stored timeseries_points (asset_price) to emulate provider response
    points = _load("timeseries_points.json")
    if not isinstance(points, list):
        points = []

    # Determine window
    if days_n == "max":
        start_dt = None
    else:
        # bound window
        d = min(max(float(days_n), 0.0416667), 3650.0)  # at least ~1h, max ~10y
        start_dt = now - datetime.timedelta(days=d)

    # select candidate points by granularity
    # Prefer hourly for short windows, otherwise daily; allow any available.
    want_hourly = (days_n != "max" and float(days_n) <= 2.0) or interval_n == "hourly"
    preferred_gran = "hourly" if want_hourly else "daily"

    def _pdt(p):
        return _parse_dt(p.get("bucket_start_at")) or _parse_dt(p.get("updated_at")) or _parse_dt(p.get("created_at"))

    rows = []
    for p in points:
        if not isinstance(p, dict):
            continue
        if p.get("series_type") != "asset_price":
            continue
        if asset_id is None or p.get("asset_id") != asset_id:
            continue
        if (p.get("quote_currency") or "").lower() != vs_currency_n:
            continue
        if p.get("status") == "invalid":
            continue
        dt = _pdt(p)
        if not dt:
            continue
        if start_dt is not None and dt < start_dt:
            continue
        rows.append((dt, p))

    # prefer preferred granularity if present
    if rows:
        has_pref = any((r[1].get("granularity") == preferred_gran) for r in rows)
        if has_pref:
            rows = [r for r in rows if r[1].get("granularity") == preferred_gran]

    rows.sort(key=lambda x: x[0])

    # CoinGecko market_chart format: arrays of [timestamp_ms, value]
    prices = []
    market_caps = []
    total_volumes = []
    for dt, p in rows:
        try:
            v = float(p.get("value"))
        except Exception:
            continue
        ts_ms = int(dt.timestamp() * 1000)
        prices.append([ts_ms, v])
        aux = p.get("aux") if isinstance(p.get("aux"), dict) else {}
        mc = aux.get("market_cap_usd") if vs_currency_n == "usd" else aux.get("market_cap")
        tv = aux.get("volume_usd") if vs_currency_n == "usd" else aux.get("volume")
        if mc is not None:
            market_caps.append([ts_ms, mc])
        if tv is not None:
            total_volumes.append([ts_ms, tv])

    payload = {
        "coin_id": coin_id_n,
        "vs_currency": vs_currency_n,
        "days": days_n,
        "interval": interval_n,
        "prices": prices,
        "market_caps": market_caps,
        "total_volumes": total_volumes,
    }

    # Cache it (short TTL)
    expires_at = (now + datetime.timedelta(hours=2)).isoformat()
    ce_row = {
        "id": "scry_cch_" + hashlib.sha256(f"{cache_key}|{now.isoformat()}".encode("utf-8")).hexdigest()[:22],
        "cache_type": "prices",
        "key": cache_key,
        "tool_name": endpoint,
        "normalized_params": normalized_params,
        "payload": payload,
        "expires_at": expires_at,
        "last_hit_at": now.isoformat(),
        "hit_count": 1,
        "compute_ms": int((time.time() - t0) * 1000),
        "status": "valid",
        "created_at": now.isoformat(),
        "updated_at": now.isoformat(),
    }
    replaced = False
    for i, ce in enumerate(cache_entries):
        if isinstance(ce, dict) and ce.get("cache_type") == "prices" and ce.get("key") == cache_key:
            ce_row["id"] = ce.get("id") or ce_row["id"]
            ce_row["hit_count"] = int(ce.get("hit_count") or 0) + 1
            cache_entries[i] = ce_row
            replaced = True
            break
    if not replaced:
        cache_entries.append(ce_row)
    _save("cache_entries.json", cache_entries)

    # Optional backfill: create/update internal_aggregated timeseries_points if none exist (idempotent)
    if asset_id is not None and prices:
        tsp = points
        if isinstance(tsp, list):
            # Backfill only if no internal_aggregated exists for these buckets
            existing_keys = set()
            for p in tsp:
                if not isinstance(p, dict):
                    continue
                if p.get("series_type") != "asset_price":
                    continue
                if p.get("asset_id") != asset_id:
                    continue
                if (p.get("quote_currency") or "").lower() != vs_currency_n:
                    continue
                if p.get("source") != "internal_aggregated":
                    continue
                if p.get("granularity") != preferred_gran:
                    continue
                dt = _parse_dt(p.get("bucket_start_at"))
                if dt:
                    existing_keys.add(int(dt.timestamp()))
            now_iso = now.isoformat()
            created = 0
            for ts_ms, val in prices[-2000:]:
                ts = int(ts_ms // 1000)
                if ts in existing_keys:
                    continue
                dt = datetime.datetime.fromtimestamp(ts, tz=datetime.timezone.utc)
                new_row = {
                    "id": "scry_tsp_" + hashlib.sha256(f"{asset_id}|{vs_currency_n}|{preferred_gran}|{ts}|internal".encode("utf-8")).hexdigest()[:22],
                    "series_type": "asset_price",
                    "asset_id": asset_id,
                    "protocol_id": None,
                    "chain": None,
                    "pool_id": None,
                    "stablecoin_symbol": None,
                    "quote_currency": vs_currency_n,
                    "bucket_start_at": dt.isoformat(),
                    "granularity": preferred_gran,
                    "value": float(val),
                    "aux": {},
                    "source": "internal_aggregated",
                    "quality_score": 0.5,
                    "status": "provisional",
                    "created_at": now_iso,
                    "updated_at": now_iso,
                }
                tsp.append(new_row)
                created += 1
            if created:
                _save("timeseries_points.json", tsp)

    _log("ok", meta={"cache_hit": False})
    return payload

def coingecko_get_trending_coins(random_string=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "coingecko_get_trending_coins"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _log(status, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{hashlib.sha256(f'{endpoint}{time.time()}'.encode()).hexdigest()[:8]}",
            "endpoint": endpoint,
            "credential": None,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    # random_string ignored intentionally (compat)

    cache_entries = _load("cache_entries.json")
    if not isinstance(cache_entries, list):
        cache_entries = []

    now = datetime.datetime.now(datetime.timezone.utc)
    cache_key = hashlib.sha256((endpoint + ":trending").encode("utf-8")).hexdigest()

    ce = None
    for row in cache_entries:
        if row.get("cache_type") == "trending" and row.get("key") == cache_key:
            ce = row
            break

    def _is_valid(row):
        if row.get("status") != "valid":
            return False
        exp = _parse_dt(row.get("expires_at"))
        if exp is not None and exp <= now:
            return False
        return isinstance(row.get("payload"), dict)

    if ce is not None and _is_valid(ce):
        ce["last_hit_at"] = _now_iso()
        ce["hit_count"] = int(ce.get("hit_count") or 0) + 1
        ce["updated_at"] = _now_iso()
        _save("cache_entries.json", cache_entries)
        _log("ok", extra={"cache": "hit"})
        return {"trending": ce["payload"], "source": "cache", "cached_at": ce.get("created_at")}

    # If expired, mark expired
    if ce is not None and ce.get("status") == "valid":
        exp = _parse_dt(ce.get("expires_at"))
        if exp is not None and exp <= now:
            ce["status"] = "expired"
            ce["updated_at"] = _now_iso()
            _save("cache_entries.json", cache_entries)

    # "Refresh from provider" offline: derive trending from local assets by heuristic popularity proxy.
    # Use active assets with a recent internal_aggregated price point in USD; rank by recency and market_cap_usd.
    assets = _load("assets.json")
    if not isinstance(assets, list):
        assets = []
    points = _load("timeseries_points.json")
    if not isinstance(points, list):
        points = []

    def _asset_latest_usd_point(asset_id):
        best = None
        best_dt = None
        for p in points:
            if p.get("series_type") != "asset_price":
                continue
            if p.get("asset_id") != asset_id:
                continue
            if (p.get("quote_currency") or "").lower() != "usd":
                continue
            if p.get("status") == "invalid":
                continue
            if p.get("source") != "internal_aggregated":
                continue
            dt = _parse_dt(p.get("bucket_start_at")) or _parse_dt(p.get("updated_at")) or _parse_dt(p.get("created_at"))
            if dt is None:
                continue
            if best_dt is None or dt > best_dt:
                best_dt = dt
                best = p
        return best_dt, best

    ranked = []
    for a in assets:
        if a.get("status") != "active":
            continue
        aid = a.get("id")
        if not isinstance(aid, str):
            continue
        dt, p = _asset_latest_usd_point(aid)
        if p is None:
            continue
        aux = p.get("aux") if isinstance(p.get("aux"), dict) else {}
        mc = aux.get("market_cap_usd")
        mc_val = float(mc) if isinstance(mc, (int, float)) else 0.0
        ranked.append((dt, mc_val, a, p))
    ranked.sort(key=lambda x: (x[0], x[1]), reverse=True)

    # CoinGecko trending response shape approximated: {coins:[{item:{...}}], nfts:[], categories:[]}
    coins = []
    for i, (_, mc_val, a, p) in enumerate(ranked[:15], start=1):
        pid = (a.get("provider_ids") or {}).get("coingecko_coin_id")
        coins.append({
            "item": {
                "id": pid or a.get("slug") or a.get("id"),
                "coin_id": pid or a.get("id"),
                "name": a.get("name"),
                "symbol": a.get("symbol"),
                "market_cap_rank": i,
                "price_btc": None,
                "score": i - 1,
                "data": {
                    "price": p.get("value"),
                    "market_cap": mc_val if mc_val > 0 else None,
                }
            }
        })

    payload = {"coins": coins, "nfts": [], "categories": []}

    # Cache with short TTL (hours)
    created = _now_iso()
    expires = (now + datetime.timedelta(hours=3)).isoformat()
    new_row = {
        "id": f"cache_{int(time.time()*1000)}_{hashlib.sha256(cache_key.encode()).hexdigest()[:10]}",
        "cache_type": "trending",
        "key": cache_key,
        "tool_name": endpoint,
        "normalized_params": {"random_string": random_string},
        "payload": payload,
        "expires_at": expires,
        "last_hit_at": created,
        "hit_count": 1,
        "compute_ms": int((time.time() - t0) * 1000),
        "status": "valid",
        "created_at": created,
        "updated_at": created,
    }
    if ce is None:
        cache_entries.append(new_row)
    else:
        ce.update({
            "tool_name": endpoint,
            "normalized_params": {"random_string": random_string},
            "payload": payload,
            "expires_at": expires,
            "last_hit_at": created,
            "compute_ms": int((time.time() - t0) * 1000),
            "status": "valid",
            "updated_at": created,
        })
        ce["hit_count"] = int(ce.get("hit_count") or 0) + 1

    _save("cache_entries.json", cache_entries)
    _log("ok", extra={"cache": "fill"})
    return {"trending": payload, "source": "local_refresh", "generated_at": created}

def get_top_protocols(limit=None, category=None, chain=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_top_protocols"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{hashlib.sha256(f'{endpoint}{time.time()}'.encode()).hexdigest()[:8]}",
            "endpoint": endpoint,
            "credential": None,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    # Validation
    if limit is None:
        limit_n = 10
    else:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "limit must be a number within [1,100]")
        if int(limit) != limit and not (isinstance(limit, float) and limit.is_integer()):
            _log("error", extra={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "limit must be an integer within [1,100]")
        limit_n = int(limit)
    if limit_n < 1 or limit_n > 100:
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be within [1,100]")

    if category is not None and (not isinstance(category, str)):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "category must be a string when provided")
    if chain is not None and (not isinstance(chain, str)):
        _log("error", extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "chain must be a string when provided")

    category_n = category.strip() if isinstance(category, str) else None
    chain_n = chain.strip() if isinstance(chain, str) else None
    if category_n == "":
        category_n = None
    if chain_n == "":
        chain_n = None

    # Cacheable response (cache_type='protocols')
    cache_entries = _load("cache_entries.json")
    if not isinstance(cache_entries, list):
        cache_entries = []
    now = datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    normalized_params = {"limit": limit_n, "category": category_n, "chain": chain_n}
    key_material = json.dumps(normalized_params, sort_keys=True, separators=(",", ":"))
    cache_key = hashlib.sha256((endpoint + ":" + key_material).encode("utf-8")).hexdigest()

    cache_row = None
    for ce in cache_entries:
        if ce.get("cache_type") == "protocols" and ce.get("key") == cache_key:
            cache_row = ce
            break

    if cache_row is not None:
        exp = _parse_dt(cache_row.get("expires_at"))
        expired = (exp is not None and exp <= now)
        if cache_row.get("status") == "valid" and not expired and isinstance(cache_row.get("payload"), dict):
            cache_row["last_hit_at"] = _now_iso()
            cache_row["hit_count"] = int(cache_row.get("hit_count") or 0) + 1
            cache_row["updated_at"] = _now_iso()
            _save("cache_entries.json", cache_entries)
            _log("ok", extra={"cache": "hit"})
            return {"protocols": cache_row["payload"].get("protocols", []), "total": cache_row["payload"].get("total", 0), "source": "cache"}

        if expired and cache_row.get("status") == "valid":
            cache_row["status"] = "expired"
            cache_row["updated_at"] = _now_iso()
            _save("cache_entries.json", cache_entries)

    protocols = _load("protocols.json")
    if not isinstance(protocols, list):
        protocols = []

    # Filter active
    filtered = []
    for p in protocols:
        if p.get("status") != "active":
            continue
        if category_n is not None:
            if (p.get("category") or "") != category_n:
                continue
        if chain_n is not None:
            chains = p.get("chains") if isinstance(p.get("chains"), list) else []
            if chain_n not in chains:
                continue
        filtered.append(p)

    if (category_n is not None or chain_n is not None) and not filtered:
        _log("error", extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "No protocols match the provided filters")

    def _num(x):
        return float(x) if isinstance(x, (int, float)) else None

    filtered.sort(key=lambda p: (_num(p.get("tvl_current_usd")) is not None, _num(p.get("tvl_current_usd")) or -1.0, p.get("defillama_slug") or ""), reverse=True)
    top = filtered[:limit_n]

    # Format response fields requested: formatted TVL, 24h change, chain distribution
    out = []
    for p in top:
        md = p.get("metadata") if isinstance(p.get("metadata"), dict) else {}
        chain_tvls = md.get("chainTvls") or md.get("chain_tvls") or md.get("chain_breakdown")
        chain_distribution = None
        if isinstance(chain_tvls, dict):
            # keep as-is but numeric-coerce where possible
            cd = {}
            for k, v in chain_tvls.items():
                cd[k] = float(v) if isinstance(v, (int, float)) else v
            chain_distribution = cd

        tvl = _num(p.get("tvl_current_usd"))
        out.append({
            "id": p.get("id"),
            "defillama_slug": p.get("defillama_slug"),
            "name": p.get("name"),
            "symbol": p.get("symbol"),
            "category": p.get("category"),
            "chains": p.get("chains") if isinstance(p.get("chains"), list) else [],
            "tvl_current_usd": tvl,
            "tvl_formatted": (f"${tvl:,.2f}" if isinstance(tvl, (int, float)) else None),
            "change_1d_pct": _num(p.get("change_1d_pct")),
            "chain_distribution": chain_distribution,
            "updated_at": p.get("updated_at"),
        })

    payload = {"protocols": out, "total": len(filtered)}

    # Cache fill (medium TTL)
    created = _now_iso()
    expires = (now + datetime.timedelta(minutes=15)).isoformat()
    new_row = {
        "id": f"cache_{int(time.time()*1000)}_{hashlib.sha256(cache_key.encode()).hexdigest()[:10]}",
        "cache_type": "protocols",
        "key": cache_key,
        "tool_name": endpoint,
        "normalized_params": normalized_params,
        "payload": payload,
        "expires_at": expires,
        "last_hit_at": created,
        "hit_count": 1,
        "compute_ms": int((time.time() - t0) * 1000),
        "status": "valid",
        "created_at": created,
        "updated_at": created,
    }
    if cache_row is None:
        cache_entries.append(new_row)
    else:
        cache_row.update({
            "tool_name": endpoint,
            "normalized_params": normalized_params,
            "payload": payload,
            "expires_at": expires,
            "last_hit_at": created,
            "compute_ms": int((time.time() - t0) * 1000),
            "status": "valid",
            "updated_at": created,
        })
        cache_row["hit_count"] = int(cache_row.get("hit_count") or 0) + 1

    _save("cache_entries.json", cache_entries)
    _log("ok", extra={"cache": "fill"})
    return {"protocols": out, "total": len(filtered), "source": "protocols.json"}

def defillama_get_protocols_paginated(page=None, limit=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_intish(v):
        if v is None:
            return None
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            return v
        if isinstance(v, float) and v.is_integer():
            return int(v)
        return None

    def _normalize_sort(sort_by, sort_order):
        allowed_sort_by = {"tvl", "name", "change_1d", "change_7d"}
        allowed_sort_order = {"asc", "desc"}
        if sort_by is None:
            sort_by = "tvl"
        if sort_order is None:
            sort_order = "desc"
        if not isinstance(sort_by, str) or sort_by not in allowed_sort_by:
            return None, None, _err("VALIDATION_ERROR", "Invalid sort_by. Must be one of: tvl, name, change_1d, change_7d")
        if not isinstance(sort_order, str) or sort_order not in allowed_sort_order:
            return None, None, _err("VALIDATION_ERROR", "Invalid sort_order. Must be one of: asc, desc")
        return sort_by, sort_order, None

    def _cache_key(obj):
        s = json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _log(status, tool_name, detail=None, cache_hit=False):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + hashlib.sha256((tool_name + "|" + _iso_now() + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:16],
                "tool_name": tool_name,
                "timestamp": _iso_now(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "cache_hit": bool(cache_hit),
                "detail": detail
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Validate inputs
    p = _parse_intish(page)
    if p is None:
        p = 1
    if p < 1:
        _log("error", "defillama_get_protocols_paginated", "page < 1")
        return _err("VALIDATION_ERROR", "page must be >= 1")

    lim = _parse_intish(limit)
    if lim is None:
        lim = 20
    if lim < 1 or lim > 100:
        _log("error", "defillama_get_protocols_paginated", "limit out of range")
        return _err("VALIDATION_ERROR", "limit must be within [1, 100]")

    sort_by, sort_order, e = _normalize_sort(sort_by, sort_order)
    if e:
        _log("error", "defillama_get_protocols_paginated", e["error"]["message"])
        return e

    # Cache lookup (optional, per business rules "may be cached per page/sort")
    normalized_params = {"page": p, "limit": lim, "sort_by": sort_by, "sort_order": sort_order}
    ck = _cache_key({"tool": "defillama_get_protocols_paginated", **normalized_params})
    cache_entries = _load("cache_entries.json")
    cache_hit = False
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    chosen_cache = None
    for ce in cache_entries if isinstance(cache_entries, list) else []:
        if ce.get("cache_type") == "protocols" and ce.get("key") == ck and ce.get("tool_name") == "defillama_get_protocols_paginated":
            # Validate cache entry lifecycle and TTL
            status = ce.get("status")
            expires_at = ce.get("expires_at")
            expired = False
            if expires_at:
                try:
                    dt = datetime.datetime.fromisoformat(expires_at.replace("Z", "+00:00"))
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                    expired = dt <= now
                except Exception:
                    expired = True
            if status == "valid" and not expired:
                chosen_cache = ce
            elif status == "valid" and expired:
                # mark expired
                try:
                    ce["status"] = "expired"
                    ce["updated_at"] = _iso_now()
                except Exception:
                    pass
            break

    if chosen_cache is not None:
        # serve from cache
        try:
            chosen_cache["hit_count"] = int(chosen_cache.get("hit_count", 0)) + 1
        except Exception:
            chosen_cache["hit_count"] = 1
        chosen_cache["last_hit_at"] = _iso_now()
        chosen_cache["updated_at"] = _iso_now()
        _save("cache_entries.json", cache_entries)
        cache_hit = True
        payload = chosen_cache.get("payload")
        _log("ok", "defillama_get_protocols_paginated", cache_hit=True)
        return payload if isinstance(payload, dict) else {
            "data": [],
            "meta": {"page": p, "limit": lim, "sort_by": sort_by, "sort_order": sort_order, "total": 0, "count": 0}
        }

    # Compute from store
    protocols = _load("protocols.json")
    if not isinstance(protocols, list):
        protocols = []

    rows = [r for r in protocols if isinstance(r, dict) and r.get("status") == "active"]

    # Sorting
    reverse = (sort_order == "desc")

    def _num_or_none(x):
        if x is None:
            return None
        if isinstance(x, (int, float)) and not isinstance(x, bool):
            return float(x)
        return None

    def _name_key(r):
        n = r.get("name")
        return (n or "").casefold()

    def _sort_key(r):
        # stable ordering with defillama_slug tie-breaker
        slug = (r.get("defillama_slug") or "").casefold()
        if sort_by == "tvl":
            v = _num_or_none(r.get("tvl_current_usd"))
            missing = (v is None)
            # Missing last regardless of order
            primary = v if v is not None else (float("-inf") if reverse else float("inf"))
            return (missing, -primary if reverse else primary, slug)
        if sort_by == "name":
            nk = _name_key(r)
            missing = (nk == "")
            return (missing, nk if not reverse else "".join(chr(0x10FFFF - ord(c)) for c in nk), slug)
        if sort_by == "change_1d":
            v = _num_or_none(r.get("change_1d_pct"))
            missing = (v is None)
            primary = v if v is not None else (float("-inf") if reverse else float("inf"))
            return (missing, -primary if reverse else primary, slug)
        if sort_by == "change_7d":
            v = _num_or_none(r.get("change_7d_pct"))
            missing = (v is None)
            primary = v if v is not None else (float("-inf") if reverse else float("inf"))
            return (missing, -primary if reverse else primary, slug)
        return (False, 0, slug)

    try:
        rows.sort(key=_sort_key)
    except Exception:
        # if something odd in data, fall back to slug sort
        rows.sort(key=lambda r: (r.get("defillama_slug") or "").casefold())

    total = len(rows)
    start = (p - 1) * lim
    end = start + lim

    if total == 0:
        # Beyond available result set only applies when there is data; empty dataset returns NOT_FOUND? tool says NOT_FOUND beyond available.
        # Here, requested page is beyond available (since no pages exist).
        _log("error", "defillama_get_protocols_paginated", "page beyond result set")
        return _err("NOT_FOUND", "Requested page is beyond available results", meta={"page": p, "limit": lim, "total": total})

    if start >= total:
        _log("error", "defillama_get_protocols_paginated", "page beyond result set")
        return _err("NOT_FOUND", "Requested page is beyond available results", meta={"page": p, "limit": lim, "total": total})

    page_rows = rows[start:end]
    payload = {
        "data": page_rows,
        "meta": {
            "page": p,
            "limit": lim,
            "sort_by": sort_by,
            "sort_order": sort_order,
            "total": total,
            "count": len(page_rows),
            "has_more": end < total,
            "total_pages": (total + lim - 1) // lim
        }
    }

    # Write cache entry (short TTL, since underlying store may change)
    created_at = _iso_now()
    expires_at = (datetime.datetime.utcnow() + datetime.timedelta(minutes=10)).replace(microsecond=0).isoformat() + "Z"
    new_entry = {
        "id": "cache_" + hashlib.sha256((ck + "|" + created_at).encode("utf-8")).hexdigest()[:16],
        "cache_type": "protocols",
        "key": ck,
        "tool_name": "defillama_get_protocols_paginated",
        "normalized_params": normalized_params,
        "payload": payload,
        "expires_at": expires_at,
        "last_hit_at": created_at,
        "hit_count": 0,
        "compute_ms": int((time.time() - t0) * 1000),
        "status": "valid",
        "created_at": created_at,
        "updated_at": created_at
    }
    cache_entries = cache_entries if isinstance(cache_entries, list) else []
    # ensure unique(cache_type,key)
    replaced = False
    for i, ce in enumerate(cache_entries):
        if isinstance(ce, dict) and ce.get("cache_type") == "protocols" and ce.get("key") == ck:
            cache_entries[i] = new_entry
            replaced = True
            break
    if not replaced:
        cache_entries.append(new_entry)
    try:
        _save("cache_entries.json", cache_entries)
    except Exception:
        pass

    _log("ok", "defillama_get_protocols_paginated", cache_hit=False)
    return payload

def defillama_get_protocols(limit=None, include_warning=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_intish(v):
        if v is None:
            return None
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            return v
        if isinstance(v, float) and v.is_integer():
            return int(v)
        return None

    def _log(status, tool_name, detail=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + hashlib.sha256((tool_name + "|" + _iso_now() + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:16],
                "tool_name": tool_name,
                "timestamp": _iso_now(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "detail": detail
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    lim = _parse_intish(limit)
    if lim is None:
        lim = 10
    if lim < 1 or lim > 50:
        _log("error", "defillama_get_protocols", "limit out of range")
        return _err("VALIDATION_ERROR", "limit must be within [1, 50]")

    if include_warning is None:
        include_warning = True
    if not isinstance(include_warning, bool):
        _log("error", "defillama_get_protocols", "include_warning not boolean")
        return _err("VALIDATION_ERROR", "include_warning must be a boolean")

    protocols = _load("protocols.json")
    if not isinstance(protocols, list):
        protocols = []

    rows = [r for r in protocols if isinstance(r, dict) and r.get("status") == "active"]

    def _tvl(r):
        v = r.get("tvl_current_usd")
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            return float(v)
        return -1.0

    rows.sort(key=lambda r: (_tvl(r), (r.get("defillama_slug") or "").casefold()), reverse=True)
    rows = rows[:lim]

    payload = {"data": rows, "meta": {"limit": lim, "count": len(rows)}}
    if include_warning:
        payload["warning"] = "DEPRECATED: Use defillama_get_top_protocols or defillama_get_protocols_paginated instead."

    _log("ok", "defillama_get_protocols")
    return payload

def defillama_search_protocols(query, limit=None, category_filter=None, chain_filter=None, min_tvl=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_intish(v):
        if v is None:
            return None
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            return v
        if isinstance(v, float) and v.is_integer():
            return int(v)
        return None

    def _log(status, tool_name, detail=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + hashlib.sha256((tool_name + "|" + _iso_now() + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:16],
                "tool_name": tool_name,
                "timestamp": _iso_now(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "detail": detail
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(query, str) or not query.strip():
        _log("error", "defillama_search_protocols", "empty query")
        return _err("VALIDATION_ERROR", "query is required and must be non-empty")

    lim = _parse_intish(limit)
    if lim is None:
        lim = 10
    if lim < 1 or lim > 50:
        _log("error", "defillama_search_protocols", "limit out of range")
        return _err("VALIDATION_ERROR", "limit must be within [1, 50]")

    if min_tvl is not None and not (isinstance(min_tvl, (int, float)) and not isinstance(min_tvl, bool)):
        _log("error", "defillama_search_protocols", "min_tvl not numeric")
        return _err("VALIDATION_ERROR", "min_tvl must be a number")

    q = query.strip().casefold()
    catf = category_filter.strip().casefold() if isinstance(category_filter, str) and category_filter.strip() else None
    chainf = chain_filter.strip().casefold() if isinstance(chain_filter, str) and chain_filter.strip() else None
    min_tvl_val = float(min_tvl) if min_tvl is not None else None

    protocols = _load("protocols.json")
    if not isinstance(protocols, list):
        protocols = []

    def _num(v):
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            return float(v)
        return None

    def _chains(r):
        c = r.get("chains")
        if isinstance(c, list):
            return [str(x) for x in c]
        return []

    # query matches name/symbol/category/aliases/slug
    results = []
    for r in protocols:
        if not isinstance(r, dict):
            continue
        if r.get("status") != "active":
            continue

        if catf:
            cat = r.get("category")
            if not (isinstance(cat, str) and cat.strip().casefold() == catf):
                continue

        if chainf:
            chs = _chains(r)
            if not any(isinstance(x, str) and x.strip().casefold() == chainf for x in chs):
                continue

        tvl = _num(r.get("tvl_current_usd"))
        if min_tvl_val is not None:
            if tvl is None or tvl < min_tvl_val:
                continue

        fields = []
        for k in ("name", "symbol", "category", "defillama_slug"):
            v = r.get(k)
            if isinstance(v, str) and v.strip():
                fields.append(v.strip().casefold())

        aliases = r.get("aliases")
        if isinstance(aliases, list):
            for a in aliases:
                if isinstance(a, str) and a.strip():
                    fields.append(a.strip().casefold())

        hay = " ".join(fields)
        if q in hay:
            results.append(r)
        else:
            # allow tokenized / fuzzy: all tokens must appear somewhere
            toks = [t for t in re.split(r"\s+", q) if t]
            if toks and all(t in hay for t in toks):
                results.append(r)

    # sort by tvl desc, tie by slug
    def _tvl_key(r):
        v = _num(r.get("tvl_current_usd"))
        return (v if v is not None else -1.0)

    results.sort(key=lambda r: (_tvl_key(r), (r.get("defillama_slug") or "").casefold()), reverse=True)
    results = results[:lim]

    if not results:
        _log("error", "defillama_search_protocols", "no matches")
        return _err("NOT_FOUND", "No protocols matched the given query and filters")

    payload = {"data": results, "meta": {"count": len(results), "limit": lim}}
    _log("ok", "defillama_search_protocols")
    return payload

def get_historical_tvl(protocol, start_date=None, end_date=None, granularity=None, max_data_points=None, days_limit=None, sample_strategy=None, include_analytics=None, include_predictions=None, **_extra):
    import json, os, datetime, time, hashlib, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, tool_name, detail=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + hashlib.sha256((tool_name + "|" + _iso_now() + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:16],
                "tool_name": tool_name,
                "timestamp": _iso_now(),
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "detail": detail
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _parse_intish(v):
        if v is None:
            return None
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            return v
        if isinstance(v, float) and v.is_integer():
            return int(v)
        return None

    def _parse_date_ymd(s):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, "Date must be a string in YYYY-MM-DD format"
        ss = s.strip()
        try:
            d = datetime.datetime.strptime(ss, "%Y-%m-%d").date()
            return d, None
        except Exception:
            return None, "Date must be in YYYY-MM-DD format"

    def _dt_from_iso(s):
        try:
            dt = datetime.datetime.fromisoformat(str(s).replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _num(v):
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            return float(v)
        return None

    if not isinstance(protocol, str) or not protocol.strip():
        _log("error", "get_historical_tvl", "missing protocol")
        return _err("VALIDATION_ERROR", "protocol is required and must be non-empty")

    if granularity is None:
        granularity = "daily"
    if not isinstance(granularity, str) or granularity not in ("hourly", "daily", "weekly"):
        _log("error", "get_historical_tvl", "invalid granularity")
        return _err("VALIDATION_ERROR", "granularity must be one of: hourly, daily, weekly")

    mdp = _parse_intish(max_data_points)
    if mdp is None:
        mdp = 500
    if mdp < 10 or mdp > 2000:
        _log("error", "get_historical_tvl", "max_data_points out of range")
        return _err("VALIDATION_ERROR", "max_data_points must be within [10, 2000]")

    if sample_strategy is None:
        sample_strategy = "even"
    if not isinstance(sample_strategy, str) or sample_strategy not in ("even", "recent", "weekly"):
        _log("error", "get_historical_tvl", "invalid sample_strategy")
        return _err("VALIDATION_ERROR", "sample_strategy must be one of: even, recent, weekly")

    if include_analytics is None:
        include_analytics = True
    if not isinstance(include_analytics, bool):
        _log("error", "get_historical_tvl", "include_analytics not boolean")
        return _err("VALIDATION_ERROR", "include_analytics must be a boolean")

    if include_predictions is None:
        include_predictions = False
    if not isinstance(include_predictions, bool):
        _log("error", "get_historical_tvl", "include_predictions not boolean")
        return _err("VALIDATION_ERROR", "include_predictions must be a boolean")

    sd, e1 = _parse_date_ymd(start_date)
    if e1:
        _log("error", "get_historical_tvl", e1)
        return _err("VALIDATION_ERROR", e1)
    ed, e2 = _parse_date_ymd(end_date)
    if e2:
        _log("error", "get_historical_tvl", e2)
        return _err("VALIDATION_ERROR", e2)

    dl = _parse_intish(days_limit)
    if sd is None and ed is None:
        if dl is None:
            dl = 30
        if dl < 7 or dl > 1095:
            _log("error", "get_historical_tvl", "days_limit out of range")
            return _err("VALIDATION_ERROR", "days_limit must be within [7, 1095]")
    else:
        # ignore days_limit when explicit dates present
        dl = None

    # Resolve protocol -> protocols.id (by exact slug/name/symbol/alias; then substring)
    protocols = _load("protocols.json")
    if not isinstance(protocols, list):
        protocols = []

    q = protocol.strip()
    q_cf = q.casefold()

    active_rows = [r for r in protocols if isinstance(r, dict) and r.get("status") == "active"]

    def _cands_exact():
        for r in active_rows:
            if (r.get("defillama_slug") or "").casefold() == q_cf:
                return r
        for r in active_rows:
            if (r.get("name") or "").casefold() == q_cf:
                return r
        for r in active_rows:
            sym = r.get("symbol")
            if isinstance(sym, str) and sym.casefold() == q_cf:
                return r
        for r in active_rows:
            aliases = r.get("aliases")
            if isinstance(aliases, list) and any(isinstance(a, str) and a.casefold() == q_cf for a in aliases):
                return r
        return None

    resolved = _cands_exact()
    if resolved is None:
        # substring/fuzzy
        best = None
        best_score = -1
        for r in active_rows:
            hay = " ".join([
                str(r.get("defillama_slug") or ""),
                str(r.get("name") or ""),
                str(r.get("symbol") or ""),
                " ".join([a for a in (r.get("aliases") or []) if isinstance(a, str)])
            ]).casefold()
            if not hay.strip():
                continue
            if q_cf in hay:
                score = 10 + (len(q_cf) / max(1, len(hay)))
            else:
                # token overlap
                qtoks = set([t for t in q_cf.split() if t])
                htoks = set([t for t in hay.replace("-", " ").split() if t])
                if not qtoks:
                    continue
                inter = len(qtoks & htoks)
                score = inter
            if score > best_score:
                best_score = score
                best = r
        resolved = best

    if resolved is None:
        _log("error", "get_historical_tvl", "protocol not found")
        return _err("NOT_FOUND", "Protocol not found")

    protocol_id = resolved.get("id")
    if not protocol_id:
        _log("error", "get_historical_tvl", "protocol missing id")
        return _err("NOT_FOUND", "Protocol not found")

    # Determine window
    today = datetime.datetime.utcnow().date()
    if sd is None and ed is None and dl is not None:
        ed = today
        sd = ed - datetime.timedelta(days=dl)
    elif sd is None and ed is not None:
        # default start based on days_limit if provided else 30
        span = dl if dl is not None else 30
        sd = ed - datetime.timedelta(days=span)
    elif sd is not None and ed is None:
        ed = today

    if sd and ed and sd > ed:
        _log("error", "get_historical_tvl", "start_date > end_date")
        return _err("VALIDATION_ERROR", "start_date must be <= end_date")

    start_dt = datetime.datetime(sd.year, sd.month, sd.day, tzinfo=datetime.timezone.utc)
    end_dt = datetime.datetime(ed.year, ed.month, ed.day, tzinfo=datetime.timezone.utc) + datetime.timedelta(days=1)  # inclusive end date

    # Fetch points
    tsp = _load("timeseries_points.json")
    if not isinstance(tsp, list):
        tsp = []

    allowed_grans = {"hourly", "daily", "weekly"}
    # business rule: retrieve protocol_tvl with granularity in ['hourly','daily','weekly']
    points = []
    for r in tsp:
        if not isinstance(r, dict):
            continue
        if r.get("series_type") != "protocol_tvl":
            continue
        if r.get("protocol_id") != protocol_id:
            continue
        g = r.get("granularity")
        if g not in allowed_grans:
            continue
        # prefer requested granularity but allow using available then downsample; here filter to <= requested? We'll first keep only requested if exists in window.
        bdt = _dt_from_iso(r.get("bucket_start_at"))
        if bdt is None:
            continue
        if not (start_dt <= bdt < end_dt):
            continue
        points.append((bdt, r))

    # If we have requested granularity points, use them; else fallback to best available among hourly/daily/weekly (prefer finer)
    by_g = {"hourly": [], "daily": [], "weekly": []}
    for bdt, r in points:
        gg = r.get("granularity")
        if gg in by_g:
            by_g[gg].append((bdt, r))

    chosen = by_g.get(granularity, [])
    if not chosen:
        # choose best available: hourly > daily > weekly
        for gg in ("hourly", "daily", "weekly"):
            if by_g[gg]:
                chosen = by_g[gg]
                break

    chosen.sort(key=lambda x: x[0])
    rows = [r for _, r in chosen]

    if not rows:
        # reads with no match => empty set (business rules didn't require NOT_FOUND here)
        payload = {
            "protocol": {"id": protocol_id, "name": resolved.get("name"), "defillama_slug": resolved.get("defillama_slug")},
            "data": [],
            "meta": {
                "granularity": granularity,
                "max_data_points": mdp,
                "sample_strategy": sample_strategy,
                "count": 0,
                "start_date": sd.isoformat() if sd else None,
                "end_date": ed.isoformat() if ed else None
            }
        }
        _log("ok", "get_historical_tvl", "no data")
        return payload

    # Downsample if needed
    def _downsample(items, target_n, strategy):
        n = len(items)
        if n <= target_n:
            return items
        if target_n <= 0:
            return []
        if strategy == "recent":
            return items[-target_n:]
        if strategy == "weekly":
            # keep weekly-ish points: one per 7 days based on bucket_start_at
            out = []
            last_kept = None
            for r in items:
                dt = _dt_from_iso(r.get("bucket_start_at"))
                if dt is None:
                    continue
                if last_kept is None or (dt - last_kept).days >= 7:
                    out.append(r)
                    last_kept = dt
            if len(out) > target_n:
                # fall back to even on out
                step = (len(out) - 1) / float(target_n - 1) if target_n > 1 else len(out)
                idxs = [int(round(i * step)) for i in range(target_n)]
                idxs = [min(len(out) - 1, max(0, k)) for k in idxs]
                uniq = []
                seen = set()
                for k in idxs:
                    if k not in seen:
                        uniq.append(out[k])
                        seen.add(k)
                return uniq
            return out
        # even
        if target_n == 1:
            return [items[-1]]
        step = (n - 1) / float(target_n - 1)
        idxs = [int(round(i * step)) for i in range(target_n)]
        idxs = [min(n - 1, max(0, k)) for k in idxs]
        uniq = []
        seen = set()
        for k in idxs:
            if k not in seen:
                uniq.append(items[k])
                seen.add(k)
        return uniq

    sampled = _downsample(rows, mdp, sample_strategy)

    # Build simplified series payload
    series = []
    for r in sampled:
        series.append({
            "bucket_start_at": r.get("bucket_start_at"),
            "value": r.get("value"),
            "granularity": r.get("granularity"),
            "source": r.get("source"),
            "status": r.get("status"),
            "aux": r.get("aux", {})
        })

    meta = {
        "granularity_requested": granularity,
        "granularity_served": sampled[0].get("granularity") if sampled else granularity,
        "max_data_points": mdp,
        "sample_strategy": sample_strategy,
        "count": len(series),
        "start_date": sd.isoformat() if sd else None,
        "end_date": ed.isoformat() if ed else None
    }

    payload = {
        "protocol": {"id": protocol_id, "name": resolved.get("name"), "defillama_slug": resolved.get("defillama_slug")},
        "data": series,
        "meta": meta
    }

    # Analytics (computed only, no mutation)
    if include_analytics and len(series) >= 2:
        vals = []
        for pt in series:
            v = _num(pt.get("value"))
            if v is not None:
                vals.append(v)
        analytics = {}
        if len(vals) >= 2:
            first, last = vals[0], vals[-1]
            analytics["start_tvl_usd"] = first
            analytics["end_tvl_usd"] = last
            analytics["absolute_change_usd"] = (last - first)
            analytics["pct_change"] = ((last - first) / first * 100.0) if first not in (0, None) else None

            # simple volatility: std dev of log returns
            rets = []
            prev = None
            for v in vals:
                if prev is not None and prev > 0 and v > 0:
                    rets.append(math.log(v / prev))
                prev = v
            if len(rets) >= 2:
                mean = sum(rets) / len(rets)
                var = sum((x - mean) ** 2 for x in rets) / (len(rets) - 1)
                analytics["volatility_log_return_std"] = math.sqrt(var)
            else:
                analytics["volatility_log_return_std"] = None

            # max drawdown
            peak = None
            max_dd = 0.0
            for v in vals:
                if peak is None or v > peak:
                    peak = v
                if peak and peak > 0:
                    dd = (peak - v) / peak
                    if dd > max_dd:
                        max_dd = dd
            analytics["max_drawdown_pct"] = max_dd * 100.0
        payload["analytics"] = analytics

    if include_predictions and len(series) >= 3:
        # naive linear trend on last N points
        vals = []
        dts = []
        for pt in series:
            v = _num(pt.get("value"))
            dt = _dt_from_iso(pt.get("bucket_start_at"))
            if v is not None and dt is not None:
                vals.append(v)
                dts.append(dt)
        pred = None
        if len(vals) >= 3:
            n = len(vals)
            xs = list(range(n))
            x_mean = sum(xs) / n
            y_mean = sum(vals) / n
            num = sum((xs[i] - x_mean) * (vals[i] - y_mean) for i in range(n))
            den = sum((xs[i] - x_mean) ** 2 for i in range(n)) or 0.0
            slope = (num / den) if den != 0.0 else 0.0
            next_val = vals[-1] + slope
            pred = {"method": "linear_trend", "next_point_estimate": max(0.0, next_val), "slope_per_step": slope}
        payload["predictions"] = pred

    _log("ok", "get_historical_tvl")
    return payload

def list_supported_protocols(category=None, chain=None, show_details=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _norm_token(s):
        s = s.strip().lower()
        s = re.sub(r"[_\s]+", "-", s)
        s = re.sub(r"[^a-z0-9\-]", "", s)
        s = re.sub(r"-{2,}", "-", s).strip("-")
        return s

    t0 = time.time()
    endpoint = "list_supported_protocols"

    # Validation
    if show_details is None:
        show_details = False
    if not isinstance(show_details, bool):
        return _err("VALIDATION_ERROR", "show_details must be a boolean")
    if category is not None and not isinstance(category, str):
        return _err("VALIDATION_ERROR", "category must be a string")
    if chain is not None and not isinstance(chain, str):
        return _err("VALIDATION_ERROR", "chain must be a string")

    protos = _load("protocols.json")

    cat_norm = _norm_token(category) if isinstance(category, str) and category.strip() != "" else None
    chain_norm = _norm_token(chain) if isinstance(chain, str) and chain.strip() != "" else None

    # Filter active protocols
    rows = [p for p in protos if isinstance(p, dict) and p.get("status") == "active"]

    if cat_norm:
        def _cat_match(p):
            c = p.get("category")
            if not isinstance(c, str) or not c.strip():
                return False
            return _norm_token(c) == cat_norm
        rows = [p for p in rows if _cat_match(p)]

    if chain_norm:
        def _chain_match(p):
            ch = p.get("chains")
            if not isinstance(ch, list):
                return False
            for x in ch:
                if isinstance(x, str) and _norm_token(x) == chain_norm:
                    return True
            return False
        rows = [p for p in rows if _chain_match(p)]

    # Business rule for this tool per description: NOT_FOUND when filters provided but no matches
    if (cat_norm or chain_norm) and len(rows) == 0:
        status = "error"
        latency_ms = int((time.time() - t0) * 1000)
        return _err("NOT_FOUND", "No supported protocols matched the provided filters", filters={"category": category, "chain": chain}, status=status, latency_ms=latency_ms)

    # Deterministic ordering for stable results
    def _sort_key(p):
        return (str(p.get("name") or "").lower(), str(p.get("defillama_slug") or ""))
    rows.sort(key=_sort_key)

    if show_details:
        out = []
        for p in rows:
            out.append({
                "id": p.get("id"),
                "defillama_slug": p.get("defillama_slug"),
                "name": p.get("name"),
                "symbol": p.get("symbol"),
                "description": p.get("description"),
                "category": p.get("category"),
                "chains": p.get("chains") if isinstance(p.get("chains"), list) else [],
                "tvl_current_usd": p.get("tvl_current_usd"),
                "change_1d_pct": p.get("change_1d_pct"),
                "change_7d_pct": p.get("change_7d_pct"),
                "metadata": p.get("metadata") if isinstance(p.get("metadata"), dict) else {},
                "aliases": p.get("aliases") if isinstance(p.get("aliases"), list) else [],
                "cache_status": p.get("cache_status"),
                "cache_updated_at": p.get("cache_updated_at"),
                "status": p.get("status"),
                "created_at": p.get("created_at"),
                "updated_at": p.get("updated_at"),
            })
    else:
        out = []
        for p in rows:
            out.append({
                "id": p.get("id"),
                "defillama_slug": p.get("defillama_slug"),
                "name": p.get("name"),
                "symbol": p.get("symbol"),
                "category": p.get("category"),
                "chains": p.get("chains") if isinstance(p.get("chains"), list) else [],
                "tvl_current_usd": p.get("tvl_current_usd"),
            })

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "object": "list",
        "data": out,
        "meta": {
            "endpoint": endpoint,
            "filters": {"category": category, "chain": chain},
            "show_details": show_details,
            "total": len(out),
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        },
    }

def resolve_protocol_name(query, show_alternatives=None, **_extra):
    import json, os, datetime, time, re, difflib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _norm(s):
        s = s.strip().lower()
        s = re.sub(r"[_\s]+", " ", s)
        s = re.sub(r"[^a-z0-9 \-]", "", s)
        s = re.sub(r"\s{2,}", " ", s).strip()
        return s

    t0 = time.time()
    endpoint = "resolve_protocol_name"

    if show_alternatives is None:
        show_alternatives = True
    if not isinstance(show_alternatives, bool):
        return _err("VALIDATION_ERROR", "show_alternatives must be a boolean")
    if not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string")
    q = query.strip()
    if not q:
        return _err("VALIDATION_ERROR", "query must be non-empty")

    protos = _load("protocols.json")
    # Only configured protocols; prefer active/hidden, exclude disabled
    candidates = []
    for p in protos:
        if not isinstance(p, dict):
            continue
        st = p.get("status")
        if st not in ("active", "hidden"):
            continue
        candidates.append(p)

    if not candidates:
        return _err("NOT_FOUND", "No configured protocols available to resolve")

    qn = _norm(q)

    # 1) Exact match: defillama_slug or name
    exact = []
    for p in candidates:
        slug = p.get("defillama_slug")
        name = p.get("name")
        if isinstance(slug, str) and _norm(slug) == qn:
            exact.append(p)
        elif isinstance(name, str) and _norm(name) == qn:
            exact.append(p)

    if len(exact) == 1:
        p = exact[0]
        latency_ms = int((time.time() - t0) * 1000)
        return {
            "resolved": {
                "id": p.get("id"),
                "defillama_slug": p.get("defillama_slug"),
                "name": p.get("name"),
                "symbol": p.get("symbol"),
                "status": p.get("status"),
            },
            "alternatives": [],
            "meta": {
                "endpoint": endpoint,
                "match_type": "exact",
                "query": query,
                "show_alternatives": show_alternatives,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
            },
        }
    if len(exact) > 1:
        # Deterministic conflict
        alts = [{
            "id": p.get("id"),
            "defillama_slug": p.get("defillama_slug"),
            "name": p.get("name"),
            "symbol": p.get("symbol"),
            "status": p.get("status"),
            "score": 1.0
        } for p in sorted(exact, key=lambda x: (str(x.get("name") or "").lower(), str(x.get("defillama_slug") or "")))]
        return _err("CONFLICT", "Ambiguous protocol query: multiple exact matches", query=query, alternatives=alts)

    # 2) Fuzzy match across name/symbol/aliases
    def _tokens_for(p):
        toks = []
        for k in ("defillama_slug", "name", "symbol"):
            v = p.get(k)
            if isinstance(v, str) and v.strip():
                toks.append(_norm(v))
        aliases = p.get("aliases")
        if isinstance(aliases, list):
            for a in aliases:
                if isinstance(a, str) and a.strip():
                    toks.append(_norm(a))
        # unique preserve order
        seen = set()
        out = []
        for t in toks:
            if t not in seen:
                out.append(t)
                seen.add(t)
        return out

    scored = []
    for p in candidates:
        best = 0.0
        best_on = None
        for t in _tokens_for(p):
            if not t:
                continue
            if t == qn:
                best = 0.99
                best_on = t
                break
            # difflib ratio is cheap and offline
            r = difflib.SequenceMatcher(None, qn, t).ratio()
            # small bonus for substring containment
            if qn and (qn in t or t in qn):
                r = min(1.0, r + 0.08)
            if r > best:
                best = r
                best_on = t
        if best > 0:
            scored.append((best, best_on, p))

    scored.sort(key=lambda x: (-x[0], str(x[2].get("tvl_current_usd") or 0.0) if x[2].get("tvl_current_usd") is not None else "", str(x[2].get("defillama_slug") or "")))

    if not scored or scored[0][0] < 0.60:
        return _err("NOT_FOUND", "No protocol matched the query", query=query)

    # Determine ambiguity: top 2 very close
    top_score = scored[0][0]
    top = scored[0][2]
    close = [s for s in scored if s[0] >= (top_score - 0.02)]
    if len(close) > 1 and top_score < 0.99:
        alts = []
        for sc, on, p in close[:10]:
            alts.append({
                "id": p.get("id"),
                "defillama_slug": p.get("defillama_slug"),
                "name": p.get("name"),
                "symbol": p.get("symbol"),
                "status": p.get("status"),
                "score": round(float(sc), 6),
                "matched_on": on,
            })
        if show_alternatives:
            return _err("CONFLICT", "Ambiguous protocol query: multiple close matches", query=query, alternatives=alts)
        else:
            return _err("CONFLICT", "Ambiguous protocol query", query=query)

    # Return resolved, optionally with alternatives
    alternatives = []
    if show_alternatives:
        for sc, on, p in scored[1:6]:
            alternatives.append({
                "id": p.get("id"),
                "defillama_slug": p.get("defillama_slug"),
                "name": p.get("name"),
                "symbol": p.get("symbol"),
                "status": p.get("status"),
                "score": round(float(sc), 6),
                "matched_on": on,
            })

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "resolved": {
            "id": top.get("id"),
            "defillama_slug": top.get("defillama_slug"),
            "name": top.get("name"),
            "symbol": top.get("symbol"),
            "status": top.get("status"),
            "score": round(float(top_score), 6),
        },
        "alternatives": alternatives,
        "meta": {
            "endpoint": endpoint,
            "match_type": "fuzzy",
            "query": query,
            "show_alternatives": show_alternatives,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        },
    }

def defillama_get_chain_historical_tvl(chain, start_timestamp=None, end_timestamp=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(x, name):
        if x is None:
            return None
        if not isinstance(x, (int, float)) or isinstance(x, bool):
            return _err("VALIDATION_ERROR", f"{name} must be a Unix timestamp in seconds (number)")
        if x < 0:
            return _err("VALIDATION_ERROR", f"{name} must be >= 0")
        # accept seconds; if clearly ms, convert
        if x > 1e12:
            x = x / 1000.0
        return int(x)

    def _norm_chain(s):
        s = s.strip()
        s_low = s.lower()
        s_low = re.sub(r"\s+", " ", s_low).strip()
        return s_low

    t0 = time.time()
    endpoint = "defillama_get_chain_historical_tvl"

    if not isinstance(chain, str) or not chain.strip():
        return _err("VALIDATION_ERROR", "chain must be a non-empty string")

    st = _parse_ts(start_timestamp, "start_timestamp")
    if isinstance(st, dict) and "error" in st:
        return st
    et = _parse_ts(end_timestamp, "end_timestamp")
    if isinstance(et, dict) and "error" in et:
        return et
    if st is not None and et is not None and st > et:
        return _err("VALIDATION_ERROR", "start_timestamp must be <= end_timestamp")

    chain_norm = _norm_chain(chain)

    points = _load("timeseries_points.json")
    chain_points = []
    for p in points:
        if not isinstance(p, dict):
            continue
        if p.get("series_type") != "chain_tvl":
            continue
        ch = p.get("chain")
        if not isinstance(ch, str):
            continue
        if _norm_chain(ch) != chain_norm:
            continue
        # Only consider non-invalid points
        if p.get("status") == "invalid":
            continue
        b = p.get("bucket_start_at")
        if not isinstance(b, str) or not b:
            continue
        # parse iso to epoch seconds
        try:
            bb = b
            if bb.endswith("Z"):
                bb = bb[:-1]
            dt = datetime.datetime.fromisoformat(bb)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            epoch = int(dt.timestamp())
        except Exception:
            continue
        if st is not None and epoch < st:
            continue
        if et is not None and epoch > et:
            continue
        chain_points.append((epoch, p))

    if not chain_points:
        return _err("NOT_FOUND", "No historical TVL data found for chain", chain=chain)

    # Choose granularity based on availability (prefer hourly if any, else daily)
    has_hourly = any(p.get("granularity") == "hourly" for _, p in chain_points)
    preferred = "hourly" if has_hourly else "daily"
    filtered = [(e, p) for (e, p) in chain_points if p.get("granularity") == preferred]
    if not filtered:
        # fallback to any available
        filtered = chain_points

    filtered.sort(key=lambda x: x[0])

    data = []
    for epoch, p in filtered:
        v = p.get("value")
        if not isinstance(v, (int, float)) or isinstance(v, bool):
            continue
        data.append({
            "timestamp": epoch,
            "date": datetime.datetime.utcfromtimestamp(epoch).strftime("%Y-%m-%d"),
            "tvl_usd": float(v),
            "granularity": p.get("granularity"),
            "source": p.get("source"),
            "quality_score": p.get("quality_score"),
            "bucket_start_at": p.get("bucket_start_at"),
        })

    if not data:
        return _err("NOT_FOUND", "No valid historical TVL points found for chain", chain=chain)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "chain": chain,
        "series_type": "chain_tvl",
        "data": data,
        "meta": {
            "endpoint": endpoint,
            "start_timestamp": st,
            "end_timestamp": et,
            "points": len(data),
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        },
    }

def defillama_get_protocol_fees_history(protocol, data_type=None, start_timestamp=None, end_timestamp=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "defillama_get_protocol_fees_history"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _stable_hash(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _log(status, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        logs.append({
            "id": "req_" + _stable_hash(f"{endpoint}|{now.isoformat()}|{len(logs)}")[:16],
            "endpoint": endpoint,
            "tool_name": endpoint,
            "status": status,
            "timestamp": now.isoformat(),
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Rate limit best-effort
    try:
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            now = _now_utc()
            cutoff = now - datetime.timedelta(seconds=60)
            recent = 0
            for r in reversed(logs[-5000:]):
                ts = _parse_dt(r.get("timestamp"))
                if not ts:
                    continue
                if ts < cutoff:
                    break
                recent += 1
            if recent >= 240:
                _log("error", meta={"error_code": "RATE_LIMIT"})
                return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
    except Exception:
        pass

    if not isinstance(protocol, str) or not protocol.strip():
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "protocol must be a non-empty string")
    slug_q = protocol.strip().lower()

    if data_type is None:
        data_type = "dailyFees"
    if not isinstance(data_type, str):
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "data_type must be a string")
    if data_type not in ("dailyFees", "dailyRevenue"):
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "data_type must be one of: dailyFees, dailyRevenue")

    def _parse_ts(x, name):
        if x is None:
            return None, None
        if isinstance(x, bool) or not isinstance(x, (int, float)):
            return _err("VALIDATION_ERROR", f"{name} must be a Unix timestamp in seconds (number)"), None
        v = float(x)
        if v < 0:
            return _err("VALIDATION_ERROR", f"{name} must be >= 0"), None
        if v > 1e12:
            v = v / 1000.0
        dt = datetime.datetime.fromtimestamp(int(v), tz=datetime.timezone.utc)
        return None, dt

    e, st_dt = _parse_ts(start_timestamp, "start_timestamp")
    if e:
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return e
    e, et_dt = _parse_ts(end_timestamp, "end_timestamp")
    if e:
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return e
    if st_dt is not None and et_dt is not None and st_dt > et_dt:
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "start_timestamp must be <= end_timestamp")

    protos = _load("protocols.json")
    if not isinstance(protos, list):
        protos = []

    # Resolve protocol: exact slug, else name match, else aliases contains
    proto_row = None
    for p in protos:
        if not isinstance(p, dict):
            continue
        s = p.get("defillama_slug")
        if isinstance(s, str) and s.strip().lower() == slug_q:
            proto_row = p
            break
    if proto_row is None:
        for p in protos:
            if not isinstance(p, dict):
                continue
            nm = p.get("name")
            if isinstance(nm, str) and nm.strip().lower() == slug_q:
                proto_row = p
                break
    if proto_row is None:
        for p in protos:
            if not isinstance(p, dict):
                continue
            aliases = p.get("aliases")
            if isinstance(aliases, list) and any(isinstance(a, str) and a.strip().lower() == slug_q for a in aliases):
                proto_row = p
                break
    if not proto_row:
        _log("error", meta={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Unknown protocol slug", protocol=protocol)

    protocol_id = proto_row.get("id")
    if not isinstance(protocol_id, str) or not protocol_id:
        _log("error", meta={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Protocol record missing id", protocol=protocol)

    series_type = "protocol_fees" if data_type == "dailyFees" else "protocol_revenue"

    tsp = _load("timeseries_points.json")
    if not isinstance(tsp, list):
        tsp = []

    rows = []
    for p in tsp:
        if not isinstance(p, dict):
            continue
        if p.get("series_type") != series_type:
            continue
        if p.get("protocol_id") != protocol_id:
            continue
        if p.get("status") == "invalid":
            continue
        dt = _parse_dt(p.get("bucket_start_at")) or _parse_dt(p.get("updated_at")) or _parse_dt(p.get("created_at"))
        if not dt:
            continue
        if st_dt is not None and dt < st_dt:
            continue
        if et_dt is not None and dt > et_dt:
            continue
        try:
            val = float(p.get("value"))
        except Exception:
            continue
