def defillama_compare_protocols_historical(protocols, start_timestamp=None, end_timestamp=None, normalize_to_start=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "defillama_compare_protocols_historical"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _stable_hash(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _log(status, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        logs.append({
            "id": "req_" + _stable_hash(f"{endpoint}|{now.isoformat()}|{len(logs)}")[:16],
            "endpoint": endpoint,
            "tool_name": endpoint,
            "status": status,
            "timestamp": now.isoformat(),
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Rate limit best-effort
    try:
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            now = _now_utc()
            cutoff = now - datetime.timedelta(seconds=60)
            recent = 0
            for r in reversed(logs[-5000:]):
                ts = _parse_dt(r.get("timestamp"))
                if not ts:
                    continue
                if ts < cutoff:
                    break
                recent += 1
            if recent >= 240:
                _log("error", meta={"error_code": "RATE_LIMIT"})
                return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
    except Exception:
        pass

    if normalize_to_start is None:
        normalize_to_start = False
    if not isinstance(normalize_to_start, bool):
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "normalize_to_start must be a boolean")

    # Relaxed to accept 1 item (audit required). If 1 -> act as single-series response.
    if not isinstance(protocols, list) or any(not isinstance(x, str) for x in protocols):
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "protocols must be an array of protocol slugs")
    cleaned = [p.strip().lower() for p in protocols if isinstance(p, str) and p.strip()]
    if not cleaned:
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "protocols must contain at least one non-empty slug")
    if len(cleaned) > 5:
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "protocols must contain at most 5 items")
    # de-dupe preserving order
    seen = set()
    uniq = []
    for p in cleaned:
        if p not in seen:
            uniq.append(p)
            seen.add(p)

    def _parse_ts(x, name):
        if x is None:
            return None, None
        if isinstance(x, bool) or not isinstance(x, (int, float)):
            return _err("VALIDATION_ERROR", f"{name} must be a Unix timestamp in seconds (number)"), None
        v = float(x)
        if v < 0:
            return _err("VALIDATION_ERROR", f"{name} must be >= 0"), None
        if v > 1e12:
            v = v / 1000.0
        dt = datetime.datetime.fromtimestamp(int(v), tz=datetime.timezone.utc)
        return None, dt

    e, st_dt = _parse_ts(start_timestamp, "start_timestamp")
    if e:
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return e
    e, et_dt = _parse_ts(end_timestamp, "end_timestamp")
    if e:
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return e
    if st_dt is not None and et_dt is not None and st_dt > et_dt:
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "start_timestamp must be <= end_timestamp")

    protos = _load("protocols.json")
    if not isinstance(protos, list):
        protos = []

    def _resolve(slug):
        # exact slug, else name, else alias
        for p in protos:
            if not isinstance(p, dict):
                continue
            s = p.get("defillama_slug")
            if isinstance(s, str) and s.strip().lower() == slug:
                return p
        for p in protos:
            if not isinstance(p, dict):
                continue
            nm = p.get("name")
            if isinstance(nm, str) and nm.strip().lower() == slug:
                return p
        for p in protos:
            if not isinstance(p, dict):
                continue
            aliases = p.get("aliases")
            if isinstance(aliases, list) and any(isinstance(a, str) and a.strip().lower() == slug for a in aliases):
                return p
        return None

    resolved = []
    for slug in uniq:
        p = _resolve(slug)
        if p and isinstance(p.get("id"), str):
            resolved.append((slug, p))
        else:
            resolved.append((slug, None))

    # If none resolve, NOT_FOUND
    if not any(p for _, p in resolved):
        _log("error", meta={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "None of the provided protocols could be resolved", protocols=uniq)

    tsp = _load("timeseries_points.json")
    if not isinstance(tsp, list):
        tsp = []

    def _pdt(row):
        return _parse_dt(row.get("bucket_start_at")) or _parse_dt(row.get("updated_at")) or _parse_dt(row.get("created_at"))

    # Collect per protocol tvl series points
    per = {}
    for slug, prow in resolved:
        if prow is None:
            continue
        pid = prow.get("id")
        pts = []
        for r in tsp:
            if not isinstance(r, dict):
                continue
            if r.get("series_type") != "protocol_tvl":
                continue
            if r.get("protocol_id") != pid:
                continue
            if r.get("status") == "invalid":
                continue
            dt = _pdt(r)
            if not dt:
                continue
            if st_dt is not None and dt < st_dt:
                continue
            if et_dt is not None and dt > et_dt:
                continue
            try:
                val = float(r.get("value"))
            except Exception:
                continue
            pts.append((dt, val))
        pts.sort(key=lambda x: x[0])
        per[slug] = pts

    # Align on intersection of timestamps across available protocols (those with data)
    nonempty = {k: v for k, v in per.items() if v}
    if not nonempty:
        # read semantics: empty aligned output
        resp = {"protocols": uniq, "start_timestamp": int(st_dt.timestamp()) if st_dt else None, "end_timestamp": int(et_dt.timestamp()) if et_dt else None, "aligned_timestamps": [], "series": {}, "normalized_series": {} if normalize_to_start else None}
        _log("ok")
        return resp

    sets = []
    for k, pts in nonempty.items():
        sets.append(set(int(dt.timestamp()) for dt, _ in pts))
    common = set.intersection(*sets) if sets else set()
    aligned_ts = sorted(common)

    series = {}
    norm_series = {} if normalize_to_start else None
    for slug, pts in nonempty.items():
        mp = {int(dt.timestamp()): val for dt, val in pts}
        vals = [[ts, mp[ts]] for ts in aligned_ts if ts in mp]
        series[slug] = vals
        if normalize_to_start:
            if vals:
                base = vals[0][1]
                if base and base != 0:
                    norm_series[slug] = [[ts, (v / base) * 100.0] for ts, v in vals]
                else:
                    norm_series[slug] = [[ts, None] for ts, _ in vals]
            else:
                norm_series[slug] = []

    resp = {
        "protocols": uniq,
        "start_timestamp": int(st_dt.timestamp()) if st_dt else None,
        "end_timestamp": int(et_dt.timestamp()) if et_dt else None,
        "aligned_timestamps": aligned_ts,
        "series": series,
        "normalized_series": norm_series,
    }
    _log("ok")
    return resp

