        alias_l = []
        for a in aliases:
            if isinstance(a, str) and a.strip():
                alias_l.append(a.strip().lower())
        if q in (slug, name, sym) or q in alias_l:
            best = p
            break

    if best is None:
        _log("error", meta={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Protocol could not be resolved", protocol=protocol)

    proto_id = best.get("id")
    if not isinstance(proto_id, str) or not proto_id:
        _log("error", meta={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Resolved protocol has no id", protocol=protocol)

    points = _load("timeseries_points.json")
    tsp_rows = points if isinstance(points, list) else (points.get("rows") if isinstance(points, dict) else [])
    tsp_rows = tsp_rows if isinstance(tsp_rows, list) else []

    now = _now_utc()
    cutoff = now - datetime.timedelta(days=float(days_limit))

    # Current: latest dex_spot_volume (for this protocol), and optionally chain breakdown from aux
    dex_points = []
    for r in tsp_rows:
        if not isinstance(r, dict):
            continue
        if r.get("series_type") != "dex_spot_volume":
            continue
        if r.get("protocol_id") != proto_id:
            continue
        ts = _parse_dt(r.get("bucket_start_at")) or _parse_dt(r.get("updated_at")) or _parse_dt(r.get("created_at"))
        if ts is None:
            continue
        dex_points.append((ts, r))
    dex_points.sort(key=lambda x: x[0])

    # Real behavior: if no dataset exists, return an empty-but-success response (not NOT_FOUND).
    latest = dex_points[-1][1] if dex_points else None

    current = None
    breakdown = None
    if latest is not None and isinstance(latest.get("value"), (int, float)):
        current = {
            "timestamp": (dex_points[-1][0].isoformat() if dex_points else None),
            "volume_usd": float(latest["value"]),
            "source": latest.get("source"),
            "status": latest.get("status"),
            "granularity": latest.get("granularity"),
        }
        if include_breakdown:
            aux = latest.get("aux") if isinstance(latest.get("aux"), dict) else {}
            cb = aux.get("chain_breakdown")
            if isinstance(cb, dict):
                breakdown = cb

    historical = []
    if include_historical and dex_points:
        for ts, r in dex_points:
            if ts < cutoff:
                continue
            if not isinstance(r.get("value"), (int, float)):
                continue
            item = {"timestamp": ts.isoformat(), "volume_usd": float(r["value"])}
            if include_breakdown:
                aux = r.get("aux") if isinstance(r.get("aux"), dict) else {}
                cb = aux.get("chain_breakdown")
                if isinstance(cb, dict):
                    item["chain_breakdown"] = cb
                elif isinstance(r.get("chain"), str) and r.get("chain"):
                    item["chain"] = r.get("chain")
            historical.append(item)

    resp = {
        "protocol": {
            "id": proto_id,
            "defillama_slug": best.get("defillama_slug"),
            "name": best.get("name"),
            "category": best.get("category"),
            "chains": best.get("chains"),
            "status": best.get("status"),
        },
        "series_type": "dex_spot_volume",
        "current": current,
        "include_historical": bool(include_historical),
        "include_breakdown": bool(include_breakdown),
        "days_limit": float(days_limit),
        "historical": historical if include_historical else [],
        "note": "No spot DEX volume points found in datastore for this protocol" if latest is None else None,
    }

    _log("ok", meta={"protocol_id": proto_id, "points": len(dex_points)})
    return resp

def get_derivatives_overview(chain=None, limit=None, include_breakdown=None, min_volume_24h=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_derivatives_overview"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _stable_hash(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _log(status, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        logs.append({
            "id": "req_" + _stable_hash(f"{endpoint}|{now.isoformat()}|{len(logs)}")[:16],
            "endpoint": endpoint,
            "tool_name": endpoint,
            "status": status,
            "timestamp": now.isoformat(),
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Rate limit best-effort
    try:
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            now = _now_utc()
            cutoff = now - datetime.timedelta(seconds=60)
            recent = 0
            for r in reversed(logs[-5000:]):
                ts = _parse_dt(r.get("timestamp"))
                if not ts:
                    continue
                if ts < cutoff:
                    break
                recent += 1
            if recent >= 240:
                _log("error", meta={"error_code": "RATE_LIMIT"})
                return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
    except Exception:
        pass

    if limit is None:
        limit_n = 20
    else:
        if isinstance(limit, bool) or not isinstance(limit, (int, float)) or int(limit) != limit:
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
        limit_n = int(limit)
    if limit_n < 1 or limit_n > 100:
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be within [1,100]")

    if include_breakdown is None:
        include_breakdown = True
    if not isinstance(include_breakdown, bool):
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_breakdown must be a boolean")

    if min_volume_24h is not None:
        if isinstance(min_volume_24h, bool) or not isinstance(min_volume_24h, (int, float)):
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "min_volume_24h must be a number when provided")
        if float(min_volume_24h) < 0:
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "min_volume_24h must be >= 0")
        min_vol = float(min_volume_24h)
    else:
        min_vol = None

    chain_n = None
    if chain is not None:
        if not isinstance(chain, str) or not chain.strip():
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "chain must be a non-empty string when provided")
        chain_n = chain.strip()

    protos = _load("protocols.json")
    if not isinstance(protos, list):
        protos = []
    tsp = _load("timeseries_points.json")
    if not isinstance(tsp, list):
        tsp = []

    # Only active protocols
    active = [p for p in protos if isinstance(p, dict) and p.get("status") == "active"]

    # Optional chain filter
    if chain_n is not None:
        filtered = []
        for p in active:
            chains = p.get("chains")
            if isinstance(chains, list) and any(isinstance(c, str) and c == chain_n for c in chains):
                filtered.append(p)
        # per business rule: if chain filter supplied and none match => NOT_FOUND
        if not filtered:
            _log("error", meta={"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "No protocols match requested chain", chain=chain_n)
        active = filtered

    now = _now_utc()
    cutoff_24h = now - datetime.timedelta(hours=24)

    def _pdt(row):
        return _parse_dt(row.get("bucket_start_at")) or _parse_dt(row.get("updated_at")) or _parse_dt(row.get("created_at"))

    # Latest derivatives_volume point per protocol (prefer newest, then quality_score, internal_aggregated)
    latest_by_pid = {}
    for r in tsp:
        if not isinstance(r, dict):
            continue
        if r.get("series_type") != "derivatives_volume":
            continue
        if r.get("status") == "invalid":
            continue
        pid = r.get("protocol_id")
        if not isinstance(pid, str) or not pid:
            continue
        dt = _pdt(r)
        if not dt:
            continue
        # allow older than 24h but compute "latest"; for 24h volume, prefer within 24h if available
        prev = latest_by_pid.get(pid)
        if prev is None:
            latest_by_pid[pid] = (dt, r)
        else:
            if dt > prev[0]:
                latest_by_pid[pid] = (dt, r)

    out_rows = []
    for p in active:
        pid = p.get("id")
        if not isinstance(pid, str) or not pid:
            continue
        latest = latest_by_pid.get(pid)
        if not latest:
            continue
        dt, r = latest
        try:
            vol = float(r.get("value"))
        except Exception:
            continue

        if min_vol is not None and vol < min_vol:
            continue

        row = {
            "protocol": p.get("defillama_slug"),
            "name": p.get("name"),
            "protocol_id": pid,
            "volume_24h_usd": vol,
            "as_of": dt.isoformat(),
        }
        if include_breakdown:
            aux = r.get("aux") if isinstance(r.get("aux"), dict) else {}
            cb = aux.get("chain_breakdown")
            if isinstance(cb, dict):
                row["chain_breakdown"] = cb
            else:
                row["chain_breakdown"] = None
        out_rows.append(row)

    out_rows.sort(key=lambda x: (-(x["volume_24h_usd"] if isinstance(x.get("volume_24h_usd"), (int, float)) else -1e30), (x.get("protocol") or "")))

    resp = {
        "chain": chain_n,
        "limit": limit_n,
        "include_breakdown": include_breakdown,
        "min_volume_24h": min_vol,
        "results": out_rows[:limit_n],
        "count": len(out_rows[:limit_n]),
        "total_candidates": len(out_rows),
    }
    _log("ok")
    return resp

