def defillama_get_cache_status(include_details=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "defillama_get_cache_status"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            try:
                return datetime.datetime.fromtimestamp(float(v), tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _stable_hash(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _log(status, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        logs.append({
            "id": "req_" + _stable_hash(f"{endpoint}|{now.isoformat()}|{len(logs)}")[:16],
            "endpoint": endpoint,
            "tool_name": endpoint,
            "status": status,
            "timestamp": now.isoformat(),
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    if include_details is None:
        include_details = False
    if not isinstance(include_details, bool):
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_details must be a boolean")

    # Rate limit status endpoint itself: 30/min
    try:
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            now = _now_utc()
            cutoff = now - datetime.timedelta(seconds=60)
            recent = 0
            for r in reversed(logs[-5000:]):
                ts = _parse_dt(r.get("timestamp"))
                if not ts:
                    continue
                if ts < cutoff:
                    break
                ep = r.get("endpoint") or r.get("tool_name")
                if ep == endpoint:
                    recent += 1
            if recent >= 30:
                _log("error", meta={"error_code": "RATE_LIMIT"})
                return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
    except Exception:
        pass

    cache_entries = _load("cache_entries.json")
    if not isinstance(cache_entries, list):
        cache_entries = []
    cache_jobs = _load("cache_jobs.json")
    if not isinstance(cache_jobs, list):
        cache_jobs = []

    now = _now_utc()

    summary = {}
    expiring_soon = 0
    expired_count = 0

    for ce in cache_entries:
        if not isinstance(ce, dict):
            continue
        ct = ce.get("cache_type") or "other"
        st = ce.get("status") or "unknown"
        summary.setdefault(ct, {}).setdefault(st, 0)
        summary[ct][st] += 1

        exp = _parse_dt(ce.get("expires_at"))
        if exp is not None:
            if exp <= now:
                expired_count += 1
            elif exp <= now + datetime.timedelta(hours=1):
                expiring_soon += 1

    latest_jobs = sorted(
        [j for j in cache_jobs if isinstance(j, dict)],
        key=lambda j: (_parse_dt(j.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)),
        reverse=True
    )[:10]

    resp = {
        "as_of": now.isoformat(),
        "entries_total": len([x for x in cache_entries if isinstance(x, dict)]),
        "entries_by_type_status": summary,
        "expired_by_ttl": expired_count,
        "expiring_within_1h": expiring_soon,
        "latest_jobs": [
            {
                "id": j.get("id"),
                "job_type": j.get("job_type"),
                "cache_type": j.get("cache_type"),
                "status": j.get("status"),
                "requested_by": j.get("requested_by"),
                "created_at": j.get("created_at"),
                "started_at": j.get("started_at"),
                "finished_at": j.get("finished_at"),
                "entries_invalidated": j.get("entries_invalidated"),
                "entries_warmed": j.get("entries_warmed"),
                "error_message": j.get("error_message"),
            } for j in latest_jobs
        ]
    }

    if include_details:
        # top keys by hit_count
        top = []
        for ce in cache_entries:
            if not isinstance(ce, dict):
                continue
            try:
                hc = int(ce.get("hit_count") or 0)
            except Exception:
                hc = 0
            top.append((hc, ce))
        top.sort(key=lambda x: x[0], reverse=True)
        resp["top_keys_by_hit_count"] = [
            {
                "cache_type": ce.get("cache_type"),
                "key": ce.get("key"),
                "tool_name": ce.get("tool_name"),
                "status": ce.get("status"),
                "hit_count": int(hc),
                "last_hit_at": ce.get("last_hit_at"),
                "expires_at": ce.get("expires_at"),
                "compute_ms": ce.get("compute_ms"),
            } for hc, ce in top[:25]
        ]

    _log("ok")
    return resp

