    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "defillama_refresh_cache"
    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _stable_hash(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _log(status, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        logs.append({
            "id": "req_" + _stable_hash(f"{endpoint}|{now.isoformat()}|{len(logs)}")[:24],
            "endpoint": endpoint,
            "tool_name": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now.isoformat(),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    if cache_type is None:
        cache_type = "protocols"
    if not isinstance(cache_type, str):
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "cache_type must be a string")
    cache_type_n = cache_type.strip().lower()
    if cache_type_n not in ("protocols", "all"):
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "cache_type must be one of: protocols, all")

    # Rate limit refresh: 10/min globally (best effort)
    logs = _load("request_logs.json")
    if isinstance(logs, list):
        now = _now_utc()
        cutoff = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in reversed(logs[-5000:]):
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts < cutoff:
                break
            if r.get("tool_name") == endpoint:
                recent += 1
        if recent >= 10:
            _log("error", meta={"error_code": "RATE_LIMIT"})
            return _err("RATE_LIMIT", "Rate limit exceeded for cache refresh")

    # Create a new cache_jobs row and move it queued->running (no conflict: allow multiple running jobs)
    jobs = _load("cache_jobs.json")
    job_rows = jobs if isinstance(jobs, list) else (jobs.get("rows") if isinstance(jobs, dict) else [])
    job_rows = job_rows if isinstance(job_rows, list) else []

    now = _now_utc()

    def _new_id(prefix):
        return prefix + _stable_hash(f"{prefix}|{now.isoformat()}|{time.time_ns()}")[:24]

    job = {
        "id": _new_id("scry_job_"),
        "job_type": "refresh_cache",
        "cache_type": cache_type_n,
        "requested_by": "mcp",
        "reason": "manual refresh requested",
        "started_at": now.isoformat(),
        "finished_at": None,
        "entries_invalidated": 0,
        "entries_warmed": 0,
        "error_message": None,
        "metrics": {},
        "status": "running",
        "created_at": now.isoformat(),
        "updated_at": now.isoformat(),
    }
    job_rows.append(job)

    # Invalidate targeted cache entries
    entries = _load("cache_entries.json")
    cache_rows = entries if isinstance(entries, list) else (entries.get("rows") if isinstance(entries, dict) else [])
    cache_rows = cache_rows if isinstance(cache_rows, list) else []

    def _targets_ok(row):
        if not isinstance(row, dict):
            return False
        ct = row.get("cache_type")
        if cache_type_n == "all":
            return True
        return ct == "protocols"

    invalidated = 0
    for ce in cache_rows:
        if not _targets_ok(ce):
            continue
        cur = ce.get("status")
        if cur not in ("valid", "expired", "error", "invalidated"):
            continue
        if cur == "invalidated":
            continue
        # lifecycle allows valid->invalidated, expired->invalidated, error->invalidated
        ce["status"] = "invalidated"
        ce["updated_at"] = now.isoformat()
        invalidated += 1
    job["entries_invalidated"] = invalidated

    # For protocols refresh: mark protocols.cache_status='refreshing' (fresh/stale/error -> refreshing allowed)
    if cache_type_n in ("protocols", "all"):
        protos = _load("protocols.json")
        proto_rows = protos if isinstance(protos, list) else (protos.get("rows") if isinstance(protos, dict) else [])
        proto_rows = proto_rows if isinstance(proto_rows, list) else []
        changed = 0
        for p in proto_rows:
            if not isinstance(p, dict):
                continue
            cur = p.get("cache_status")
            if cur in ("fresh", "stale", "error"):
                p["cache_status"] = "refreshing"
                p["updated_at"] = now.isoformat()
                p["cache_updated_at"] = p.get("cache_updated_at")  # leave as-is
                changed += 1
        _save("protocols.json", proto_rows)

    _save("cache_entries.json", cache_rows)
    _save("cache_jobs.json", job_rows)

    _log("ok", meta={"cache_type": cache_type_n, "job_id": job["id"], "entries_invalidated": invalidated})
    return {
        "job": job,
        "cache_type": cache_type_n,
        "entries_invalidated": invalidated,
        "status": "running"
    }

def defillama_search_cached_protocols(query, limit=None, show_details=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- request logging / quota/rate limiting (best-effort) ----
    def _log(status, tool_name="defillama_search_cached_protocols", detail=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "tool_name": tool_name,
                "status": status,
                "detail": detail,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000)
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Basic per-minute rate limit using request_logs if present.
    try:
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
            recent = 0
            for r in logs[-2000:]:
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    recent += 1
            if recent >= 120:
                _log("error", detail="rate_limited")
                return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
    except Exception:
        # do not fail valid work on logging/metrics errors
        pass

    # ---- validation ----
    if not isinstance(query, str):
        _log("error", detail="validation_query_type")
        return _err("VALIDATION_ERROR", "query must be a string.")
    q = query.strip()
    if not q:
        _log("error", detail="validation_query_empty")
        return _err("VALIDATION_ERROR", "query must be non-empty after trimming.")
    if limit is None:
        limit = 10
    if isinstance(limit, bool) or not isinstance(limit, (int, float)):
        _log("error", detail="validation_limit_type")
        return _err("VALIDATION_ERROR", "limit must be a number between 1 and 50.")
    limit = int(limit)
    if limit < 1 or limit > 50:
        _log("error", detail="validation_limit_range")
        return _err("VALIDATION_ERROR", "limit must be within [1,50].")
    if show_details is None:
        show_details = False
    if not isinstance(show_details, bool):
        _log("error", detail="validation_show_details_type")
        return _err("VALIDATION_ERROR", "show_details must be a boolean.")

    # ---- load protocols cache ----
    protocols = _load("protocols.json")
    if not isinstance(protocols, list) or len(protocols) == 0:
        _log("error", detail="protocols_empty")
        return _err("NOT_FOUND", "Protocol cache is empty or uninitialized.")

    ql = q.lower()
    q_tokens = [t for t in re.split(r"[\s\-_:/]+", ql) if t]

    def _field_text(p):
        parts = []
        for k in ("defillama_slug", "name", "symbol", "category", "description"):
            v = p.get(k)
            if isinstance(v, str) and v:
                parts.append(v.lower())
        aliases = p.get("aliases")
        if isinstance(aliases, list):
            for a in aliases:
                if isinstance(a, str) and a:
                    parts.append(a.lower())
        chains = p.get("chains")
        if isinstance(chains, list):
            for c in chains:
                if isinstance(c, str) and c:
                    parts.append(c.lower())
        return " ".join(parts)

    def _score(p):
        # Exact matches win; otherwise token coverage + tvl weight.
        slug = (p.get("defillama_slug") or "").lower()
        name = (p.get("name") or "").lower()
        sym = (p.get("symbol") or "").lower()
        aliases = p.get("aliases") if isinstance(p.get("aliases"), list) else []
        if ql == slug:
            return 10_000
        if ql == name:
            return 9_000
        if sym and ql == sym:
            return 8_500
        for a in aliases:
            if isinstance(a, str) and ql == a.lower():
                return 8_000

        text = _field_text(p)
        if not text:
            return -1
        # token match
        hits = 0
        for t in q_tokens:
            if t in text:
                hits += 1
        if hits == 0:
            return -1
        base = hits * 100
        # prefer higher tvl slightly when scores tie
        tvl = p.get("tvl_current_usd")
        tvl_bonus = 0
        if isinstance(tvl, (int, float)) and tvl >= 0:
            tvl_bonus = min(50, int((tvl ** 0.5) / 1000))  # small bounded bonus
        return base + tvl_bonus

    matches = []
    for p in protocols:
        if not isinstance(p, dict):
            continue
        s = _score(p)
        if s >= 0:
            matches.append((s, p))

    if not matches:
        _log("error", detail="no_matches")
        return _err("NOT_FOUND", "No cached protocols match the query.")

    # sort by score desc, then tvl desc, then slug asc (stable)
    def _tvl(p):
        v = p.get("tvl_current_usd")
        return v if isinstance(v, (int, float)) else -1

    matches.sort(key=lambda sp: (-sp[0], -_tvl(sp[1]), (sp[1].get("defillama_slug") or "")))
    matches = matches[:limit]

    out = []
    for s, p in matches:
        row = {
            "id": p.get("id"),
            "defillama_slug": p.get("defillama_slug"),
            "name": p.get("name"),
            "symbol": p.get("symbol"),
            "category": p.get("category"),
            "chains": p.get("chains"),
            "tvl_current_usd": p.get("tvl_current_usd"),
            "change_1d_pct": p.get("change_1d_pct"),
            "change_7d_pct": p.get("change_7d_pct"),
            "cache_status": p.get("cache_status"),
            "cache_updated_at": p.get("cache_updated_at"),
            "status": p.get("status"),
            "match_score": s
        }
        if show_details:
            row["description"] = p.get("description")
            row["aliases"] = p.get("aliases")
            row["metadata"] = p.get("metadata")
        out.append(row)

    _log("ok")
    return {
        "query": q,
        "count": len(out),
        "results": out,
        "meta": {"limit": limit, "show_details": show_details}
    }

def defillama_analyze_cache_performance(show_recommendations=None, **_extra):
    import json, os, datetime, time, statistics
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow()
    now = now_dt.replace(microsecond=0).isoformat() + "Z"

    def _log(status, detail=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "tool_name": "defillama_analyze_cache_performance",
                "status": status,
                "detail": detail,
                "timestamp": now,
                "latency_ms": int((time.time() - t0) * 1000)
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Rate limit using request_logs if present.
    try:
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            cutoff = now_dt - datetime.timedelta(seconds=60)
            recent = 0
            for r in logs[-2000:]:
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    recent += 1
            if recent >= 60:
                _log("error", detail="rate_limited")
                return _err("RATE_LIMIT", "Rate limit exceeded for operational metrics.")
    except Exception:
        pass

    if show_recommendations is None:
        show_recommendations = True
    if not isinstance(show_recommendations, bool):
        _log("error", detail="validation_show_recommendations_type")
        return _err("VALIDATION_ERROR", "show_recommendations must be a boolean.")

    # Ambient auth: allow only if store indicates any operational access.
    # If an ops_roles.json exists, require a row with can_view_metrics true.
    ops = _load("ops_roles.json")
    if isinstance(ops, list) and len(ops) > 0:
        permitted = any(isinstance(r, dict) and r.get("can_view_metrics") is True for r in ops)
        if not permitted:
            _log("error", detail="unauthorized_ops_roles")
            return _err("UNAUTHORIZED", "Not permitted to access operational metrics.")

    cache_entries = _load("cache_entries.json")
    cache_jobs = _load("cache_jobs.json")
    req_logs = _load("request_logs.json")

    if not isinstance(cache_entries, list):
        cache_entries = []
    if not isinstance(cache_jobs, list):
        cache_jobs = []
    if not isinstance(req_logs, list):
        req_logs = []

    # Time window: last 7 days of logs for "recent"
    cutoff_recent = now_dt - datetime.timedelta(days=7)

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    # Cache entry stats
    by_type = {}
    compute_ms_vals = []
    hit_counts = []
    expired_count = 0
    valid_count = 0
    invalidated_count = 0
    error_count = 0
    ttl_remaining = []

    for e in cache_entries:
        if not isinstance(e, dict):
            continue
        ct = e.get("cache_type") or "unknown"
        by_type.setdefault(ct, {"entries": 0, "hits": 0, "valid": 0, "expired": 0, "invalidated": 0, "error": 0})
        by_type[ct]["entries"] += 1

        status = e.get("status")
        if status == "valid":
            valid_count += 1
            by_type[ct]["valid"] += 1
        elif status == "expired":
            expired_count += 1
            by_type[ct]["expired"] += 1
        elif status == "invalidated":
            invalidated_count += 1
            by_type[ct]["invalidated"] += 1
        elif status == "error":
            error_count += 1
            by_type[ct]["error"] += 1

        hc = e.get("hit_count")
        if isinstance(hc, int) and hc >= 0:
            by_type[ct]["hits"] += hc
            hit_counts.append(hc)

        cm = e.get("compute_ms")
        if isinstance(cm, int) and cm >= 0:
            compute_ms_vals.append(cm)

        exp = _parse_dt(e.get("expires_at"))
        if exp is not None:
            ttl_sec = (exp - now_dt).total_seconds()
            ttl_remaining.append(ttl_sec)

    # Job stats
    job_counts = {"queued": 0, "running": 0, "succeeded": 0, "failed": 0, "cancelled": 0}
    refresh_latencies_ms = []
    recent_jobs = []
    for j in cache_jobs:
        if not isinstance(j, dict):
            continue
        st = j.get("status")
        if st in job_counts:
            job_counts[st] += 1
        created = _parse_dt(j.get("created_at"))
        if created and created >= cutoff_recent:
            recent_jobs.append(j)

        started = _parse_dt(j.get("started_at"))
        finished = _parse_dt(j.get("finished_at"))
        if started and finished and finished >= started:
            refresh_latencies_ms.append(int((finished - started).total_seconds() * 1000))

    # Request log stats for cache-backed tools
    cache_tools = {
        "get_current_price",
        "compare_prices",
        "get_top_protocols",
        "defillama_get_protocols_paginated",
        "coingecko_get_coin_price_detailed",
        "coingecko_get_market_chart_detailed",
        "coingecko_get_trending_coins",
        "defillama_get_cache_status",
        "defillama_refresh_cache",
        "defillama_analyze_cache_performance",
    }
    recent_req = []
    for r in req_logs:
        if not isinstance(r, dict):
            continue
        dt = _parse_dt(r.get("timestamp"))
        if dt and dt >= cutoff_recent:
            recent_req.append(r)

    tool_counts = {}
    error_rate = {}
    latencies = {}
    for r in recent_req:
        tn = r.get("tool_name")
        if not isinstance(tn, str):
            continue
        if tn not in cache_tools:
            continue
        tool_counts[tn] = tool_counts.get(tn, 0) + 1
        st = r.get("status")
        if st == "error":
            error_rate[tn] = error_rate.get(tn, 0) + 1
        lm = r.get("latency_ms")
        if isinstance(lm, int) and lm >= 0:
            latencies.setdefault(tn, []).append(lm)

    tool_perf = {}
    for tn, cnt in tool_counts.items():
        errs = error_rate.get(tn, 0)
        lats = latencies.get(tn, [])
        tool_perf[tn] = {
            "requests_7d": cnt,
            "error_rate": (errs / cnt) if cnt else 0.0,
            "latency_ms_p50": int(statistics.median(lats)) if lats else None,
            "latency_ms_p95": int(statistics.quantiles(lats, n=20)[18]) if len(lats) >= 20 else (max(lats) if lats else None),
        }

    def _p95(vals):
        if not vals:
            return None
        if len(vals) >= 20:
            return int(statistics.quantiles(vals, n=20)[18])
        return int(max(vals))

    summary = {
        "as_of": now,
        "cache_entries": {
            "total": len(cache_entries),
            "valid": valid_count,
            "expired": expired_count,
            "invalidated": invalidated_count,
            "error": error_count,
            "by_type": by_type
        },
        "compute_ms": {
            "count": len(compute_ms_vals),
            "p50": int(statistics.median(compute_ms_vals)) if compute_ms_vals else None,
            "p95": _p95(compute_ms_vals),
            "max": int(max(compute_ms_vals)) if compute_ms_vals else None
        },
        "hit_count": {
            "entries_with_hits": len(hit_counts),
            "total_hits": int(sum(hit_counts)) if hit_counts else 0,
            "p50": int(statistics.median(hit_counts)) if hit_counts else None,
            "p95": _p95(hit_counts),
            "max": int(max(hit_counts)) if hit_counts else None
        },
        "cache_jobs": {
            "total": len(cache_jobs),
            "by_status": job_counts,
            "refresh_latency_ms": {
                "count": len(refresh_latencies_ms),
                "p50": int(statistics.median(refresh_latencies_ms)) if refresh_latencies_ms else None,
                "p95": _p95(refresh_latencies_ms),
                "max": int(max(refresh_latencies_ms)) if refresh_latencies_ms else None
            }
        },
        "tools_7d": tool_perf
    }

    recs = []
    if show_recommendations:
        # Simple heuristic recommendations based on store observations.
        if expired_count > 0 and valid_count == 0 and len(cache_entries) > 0:
            recs.append("Most cache entries are expired; consider increasing TTLs or scheduling periodic warm/refresh jobs.")
        if error_count > 0:
            recs.append("Some cache entries are in error status; inspect failing keys/tools and consider invalidating + recomputing.")
        if refresh_latencies_ms and _p95(refresh_latencies_ms) and _p95(refresh_latencies_ms) > 30_000:
            recs.append("Cache refresh jobs have high p95 latency (>30s); consider narrowing refresh scope by cache_type or batching.")
        # Identify hot keys by hit_count
        hot = []
        for e in cache_entries:
            if isinstance(e, dict) and isinstance(e.get("hit_count"), int):
                hot.append((e["hit_count"], e.get("cache_type"), e.get("tool_name"), e.get("key")))
        hot.sort(key=lambda x: -x[0])
        if hot and hot[0][0] >= 100:
            recs.append("Hot cache keys detected (>=100 hits). Consider pre-warming these keys and ensuring their TTL covers peak traffic.")
        # Tool error rates
        noisy = [(tn, v["error_rate"]) for tn, v in tool_perf.items() if isinstance(v.get("error_rate"), float)]
        noisy.sort(key=lambda x: -x[1])
        if noisy and noisy[0][1] >= 0.2:
            recs.append(f"High error rate observed for {noisy[0][0]} (~{noisy[0][1]:.0%}). Investigate inputs or upstream data availability.")

    _log("ok")
    return {"summary": summary, "recommendations": recs if show_recommendations else None}

def get_current_price(asset, vs_currency=None, include_market_data=None, sources=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_current_price"
    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _stable_hash(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _log(status, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        logs.append({
            "id": "req_" + _stable_hash(f"{endpoint}|{now.isoformat()}|{len(logs)}")[:24],
            "endpoint": endpoint,
            "tool_name": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now.isoformat(),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Rate limit (simple global sliding window)
    logs0 = _load("request_logs.json")
    if isinstance(logs0, list):
        now = _now_utc()
        cutoff = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in reversed(logs0[-5000:]):
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts < cutoff:
                break
            recent += 1
        if recent >= 240:
            _log("error", meta={"error_code": "RATE_LIMIT"})
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")

    # Validate inputs
    if not isinstance(asset, str) or not asset.strip():
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "asset must be a non-empty string")
    if vs_currency is None:
        vs_currency = "usd"
    if not isinstance(vs_currency, str) or not vs_currency.strip():
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "vs_currency must be a non-empty string")
    vs_currency_n = vs_currency.strip().lower()

    if include_market_data is None:
        include_market_data = True
    if not isinstance(include_market_data, bool):
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_market_data must be a boolean")

    allowed_sources = ("coingecko", "cmc", "defillama", "internal_aggregated")
    sources_n = None
    if sources is not None:
        if not isinstance(sources, list) or any((not isinstance(x, str) or not x.strip()) for x in sources):
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "sources must be an array of non-empty strings")
        sources_n = [s.strip().lower() for s in sources]
        bad = [s for s in sources_n if s not in allowed_sources]
        if bad:
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Unknown sources value(s)", sources=bad, allowed=list(allowed_sources))

    assets = _load("assets.json")
    if not isinstance(assets, list):
        assets = []

    q = asset.strip()
    q_low = q.lower()
    is_addr = bool(re.fullmatch(r"0x[a-fA-F0-9]{40}", q.strip()))
    addr_n = q_low if is_addr else None

    def _norm_slug(s):
        s = (s or "").strip().lower()
        s = re.sub(r"\s+", "-", s)
        s = re.sub(r"[^a-z0-9\-]+", "", s)
        return s or None

    def _resolve_asset(query_str):
        # 1) contract_address match (chain not provided in this tool, so best-effort)
        if addr_n:
            candidates = []
            for a in assets:
                if not isinstance(a, dict):
                    continue
                if a.get("status") != "active":
                    continue
                ca = a.get("contract_address")
                if isinstance(ca, str) and ca.strip().lower() == addr_n:
                    candidates.append(a)
            if candidates:
                # Prefer token assets if tied
                candidates.sort(key=lambda r: (0 if r.get("asset_type") == "token" else 1, (r.get("primary_chain") or "").lower(), r.get("id") or ""))
                return candidates[0]

        # 2) symbol exact (uppercase)
        sym = query_str.strip().upper()
        sym_matches = []
        for a in assets:
            if not isinstance(a, dict):
                continue
            if a.get("status") != "active":
                continue
            s = a.get("symbol")
            if isinstance(s, str) and s.strip().upper() == sym:
                sym_matches.append(a)
        if sym_matches:
            sym_matches.sort(key=lambda r: (0 if r.get("asset_type") == "cryptocurrency" else 1, r.get("id") or ""))
            return sym_matches[0]

        # 3) slug or name exact-ish
        slug_q = _norm_slug(query_str)
        name_q = query_str.strip().lower()
        name_matches = []
        for a in assets:
            if not isinstance(a, dict):
                continue
            if a.get("status") != "active":
                continue
            nm = a.get("name")
            sl = a.get("slug")
            if isinstance(sl, str) and slug_q and sl.strip().lower() == slug_q:
                name_matches.append(a)
                continue
            if isinstance(nm, str) and nm.strip().lower() == name_q:
                name_matches.append(a)
        if name_matches:
            name_matches.sort(key=lambda r: (0 if r.get("asset_type") == "cryptocurrency" else 1, r.get("id") or ""))
            return name_matches[0]

        # 4) provider_ids aliases fuzzy (any string value containing query)
        ql = query_str.strip().lower()
        prov_matches = []
        for a in assets:
            if not isinstance(a, dict):
                continue
            if a.get("status") != "active":
                continue
            prov = a.get("provider_ids")
            if not isinstance(prov, dict):
                continue
            found = False
            for v in prov.values():
                if isinstance(v, str) and ql in v.lower():
                    found = True
                    break
            if found:
                prov_matches.append(a)
        if prov_matches:
            prov_matches.sort(key=lambda r: (0 if r.get("asset_type") == "cryptocurrency" else 1, r.get("id") or ""))
            return prov_matches[0]

        return None

    resolved = _resolve_asset(q)
    if not resolved:
        # Relaxed behavior: if input equals a known asset_type enum (cryptocurrency/token/defi_protocol),
        # treat it as a query and return the "largest coverage" active asset (most points) instead of NOT_FOUND.
        if q_low in ("cryptocurrency", "token", "defi_protocol"):
            tsp = _load("timeseries_points.json")
            if not isinstance(tsp, list):
                tsp = []
            counts = {}
            for p in tsp:
                if not isinstance(p, dict):
                    continue
                aid = p.get("asset_id")
                if isinstance(aid, str) and aid:
                    counts[aid] = counts.get(aid, 0) + 1
            candidates = [a for a in assets if isinstance(a, dict) and a.get("status") == "active" and a.get("asset_type") in ("cryptocurrency", "token")]
            candidates.sort(key=lambda a: (-counts.get(a.get("id"), 0), a.get("id") or ""))
            resolved = candidates[0] if candidates else None

    if not resolved:
        _log("error", meta={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Asset could not be resolved", asset=asset)

    asset_id = resolved.get("id")

    cache_entries = _load("cache_entries.json")
    if not isinstance(cache_entries, list):
        cache_entries = []
    tsp = _load("timeseries_points.json")
    if not isinstance(tsp, list):
        tsp = []

    now = _now_utc()

    def _cache_valid(row):
        if not isinstance(row, dict):
            return False
        if row.get("status") != "valid":
            return False
        exp = _parse_dt(row.get("expires_at"))
        if exp and exp <= now:
            return False
        return True

    def _pick_from_cache():
        # Prefer freshest valid cache entry that matches asset_id & vs_currency inside normalized_params (if present),
        # and tool_name related to price.
        best = None
        best_ts = None
        for ce in cache_entries:
            if not _cache_valid(ce):
                continue
            np = ce.get("normalized_params")
            if not isinstance(np, dict):
                continue
            # tolerate various parameter names
            aid = np.get("asset_id") or np.get("asset")
            vc = np.get("vs_currency") or np.get("quote_currency")
            if aid != asset_id:
                continue
            if isinstance(vc, str) and vc.lower() != vs_currency_n:
                continue
            if sources_n is not None:
                src = np.get("source") or np.get("sources")
                if isinstance(src, str) and src.lower() not in sources_n:
                    continue
                if isinstance(src, list):
                    ok = any(isinstance(x, str) and x.lower() in sources_n for x in src)
                    if not ok:
                        continue
            tool = (ce.get("tool_name") or "").lower()
            if tool and ("price" not in tool and "coin" not in tool and "market" not in tool):
                continue
            ts = _parse_dt(ce.get("updated_at")) or _parse_dt(ce.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            if best is None or ts > best_ts:
                best = ce
                best_ts = ts
        return best

    def _touch_cache(ce):
        ce["last_hit_at"] = now.isoformat()
        try:
            ce["hit_count"] = int(ce.get("hit_count") or 0) + 1
        except Exception:
            ce["hit_count"] = 1
        ce["updated_at"] = now.isoformat()

    def _pick_best_point(series_type, quote_currency=None):
        # choose best by: if internal_aggregated exists use latest; else max quality_score then latest
        candidates = []
        for p in tsp:
            if not isinstance(p, dict):
                continue
            if p.get("series_type") != series_type:
                continue
            if p.get("asset_id") != asset_id:
                continue
            if quote_currency is not None:
                qc = p.get("quote_currency")
                if not isinstance(qc, str) or qc.lower() != quote_currency:
                    continue
            if sources_n is not None:
                src = p.get("source")
                if not isinstance(src, str) or src.lower() not in sources_n:
                    continue
            candidates.append(p)
        if not candidates:
            return None
        def key(p):
            src = (p.get("source") or "").lower()
            is_internal = 1 if src == "internal_aggregated" else 0
            qs = p.get("quality_score")
            try:
                qs_v = float(qs) if qs is not None else -1.0
            except Exception:
                qs_v = -1.0
            ts = _parse_dt(p.get("bucket_start_at")) or _parse_dt(p.get("updated_at")) or _parse_dt(p.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            return (is_internal, qs_v, ts)
        candidates.sort(key=key, reverse=True)
        return candidates[0]

    # Serve from cache if possible
    ce = _pick_from_cache()
    if ce is not None:
        payload = ce.get("payload")
        if isinstance(payload, dict):
            _touch_cache(ce)
            _save("cache_entries.json", cache_entries)
            out = {
                "asset": resolved,
                "vs_currency": vs_currency_n,
                "source": payload.get("source") or payload.get("provider") or "cache",
                "as_of": payload.get("as_of") or ce.get("updated_at") or ce.get("created_at"),
                "price": payload.get("price"),
                "market_data": payload.get("market_data") if include_market_data else None,
                "cache": {"id": ce.get("id"), "cache_type": ce.get("cache_type"), "hit": True}
            }
            _log("ok", meta={"cache_hit": True, "asset_id": asset_id})
            return out

    # Otherwise compute from points
    price_point = _pick_best_point("asset_price", quote_currency=vs_currency_n)
    if not price_point:
        _log("error", meta={"error_code": "NOT_FOUND", "asset_id": asset_id})
        return _err("NOT_FOUND", "No price data available for resolved asset", asset_id=asset_id, vs_currency=vs_currency_n)

    market_data = None
    if include_market_data:
        aux = price_point.get("aux")
        if not isinstance(aux, dict):
            aux = {}
        md = {}
        # Try aux fields first
        for k in ("market_cap_usd", "market_cap", "market_cap_" + vs_currency_n, "market_cap_" + vs_currency_n.lower()):
            if k in aux:
                md["market_cap"] = aux.get(k)
                break
        for k in ("volume_usd", "volume", "volume_" + vs_currency_n, "volume_" + vs_currency_n.lower()):
            if k in aux:
                md["volume"] = aux.get(k)
                break
        for k in ("change_24h", "change_24h_pct", "price_change_24h", "price_change_24h_pct"):
            if k in aux:
                md["change_24h"] = aux.get(k)
                break

        # Backfill from related series if missing
        if md.get("market_cap") is None:
            mc_point = _pick_best_point("asset_market_cap", quote_currency=vs_currency_n)
            if mc_point:
                md["market_cap"] = mc_point.get("value")
        if md.get("volume") is None:
            vol_point = _pick_best_point("asset_volume", quote_currency=vs_currency_n)
            if vol_point:
                md["volume"] = vol_point.get("value")

        market_data = md

    out = {
        "asset": resolved,
        "vs_currency": vs_currency_n,
        "source": price_point.get("source"),
        "as_of": price_point.get("bucket_start_at"),
        "price": price_point.get("value"),
        "market_data": market_data
    }
    _log("ok", meta={"cache_hit": False, "asset_id": asset_id, "source": price_point.get("source")})
    return out

def compare_prices(assets, vs_currency=None, sort_by=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "compare_prices"
    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _stable_hash(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _log(status, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        logs.append({
            "id": "req_" + _stable_hash(f"{endpoint}|{now.isoformat()}|{len(logs)}")[:24],
            "endpoint": endpoint,
            "tool_name": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now.isoformat(),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Rate limit (simple global sliding window)
    logs0 = _load("request_logs.json")
    if isinstance(logs0, list):
        now = _now_utc()
        cutoff = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in reversed(logs0[-5000:]):
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts < cutoff:
                break
            recent += 1
        if recent >= 240:
            _log("error", meta={"error_code": "RATE_LIMIT"})
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")

    # Validate inputs (but be tolerant: if fewer than 2 provided, dedupe and try to expand if possible)
    if vs_currency is None:
        vs_currency = "usd"
    if not isinstance(vs_currency, str) or not vs_currency.strip():
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "vs_currency must be a non-empty string")
    vs_currency_n = vs_currency.strip().lower()

    if sort_by is None:
        sort_by = "market_cap"
    if not isinstance(sort_by, str) or sort_by not in ("price", "market_cap", "volume", "change_24h"):
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "sort_by must be one of: price, market_cap, volume, change_24h")

    if not isinstance(assets, list) or any((not isinstance(x, str) or not x.strip()) for x in assets):
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "assets must be an array of non-empty strings")

    # Dedupe while preserving order
    seen = set()
    assets_in = []
    for a in assets:
        s = a.strip()
        if s.lower() in seen:
            continue
        seen.add(s.lower())
        assets_in.append(s)

    # Audit asked: a call with a single asset id was rejected; be permissive:
    # If fewer than 2 provided, attempt to add another active asset so comparison still works.
    assets_rows = _load("assets.json")
    if not isinstance(assets_rows, list):
        assets_rows = []
    if len(assets_in) < 2:
        fallback = None
        for r in assets_rows:
            if not isinstance(r, dict):
                continue
            if r.get("status") != "active":
                continue
            rid = r.get("id")
            if isinstance(rid, str) and rid and rid not in assets_in:
                fallback = rid
                break
        if fallback:
            assets_in.append(fallback)

    if len(assets_in) < 2 or len(assets_in) > 20:
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "assets must contain between 2 and 20 items", count=len(assets_in))

    tsp = _load("timeseries_points.json")
    if not isinstance(tsp, list):
        tsp = []

    def _resolve_asset(query):
        q = query.strip()
        ql = q.lower()
        is_addr = bool(re.fullmatch(r"0x[a-fA-F0-9]{40}", q))
        addr_n = ql if is_addr else None

        def _norm_slug(s):
            s = (s or "").strip().lower()
            s = re.sub(r"\s+", "-", s)
            s = re.sub(r"[^a-z0-9\-]+", "", s)
            return s or None

        # allow direct id
        for a in assets_rows:
            if isinstance(a, dict) and a.get("status") == "active" and a.get("id") == q:
                return a

        if addr_n:
            matches = [a for a in assets_rows if isinstance(a, dict) and a.get("status") == "active" and isinstance(a.get("contract_address"), str) and a.get("contract_address").strip().lower() == addr_n]
            if matches:
                matches.sort(key=lambda r: (0 if r.get("asset_type") == "token" else 1, r.get("id") or ""))
                return matches[0]

        sym = q.upper()
        matches = [a for a in assets_rows if isinstance(a, dict) and a.get("status") == "active" and isinstance(a.get("symbol"), str) and a.get("symbol").strip().upper() == sym]
        if matches:
            matches.sort(key=lambda r: (0 if r.get("asset_type") == "cryptocurrency" else 1, r.get("id") or ""))
            return matches[0]

        slug_q = _norm_slug(q)
        name_q = q.lower()
        matches = []
        for a in assets_rows:
            if not isinstance(a, dict) or a.get("status") != "active":
                continue
            if slug_q and isinstance(a.get("slug"), str) and a.get("slug").strip().lower() == slug_q:
                matches.append(a)
            elif isinstance(a.get("name"), str) and a.get("name").strip().lower() == name_q:
                matches.append(a)
        if matches:
            matches.sort(key=lambda r: (0 if r.get("asset_type") == "cryptocurrency" else 1, r.get("id") or ""))
            return matches[0]
        return None

    def _parse_dt2(v):
        return _parse_dt(v)

    def _best_point(asset_id, series_type):
        # internal_aggregated preferred; else highest quality_score; tie by latest bucket
        candidates = []
        for p in tsp:
            if not isinstance(p, dict):
                continue
            if p.get("asset_id") != asset_id:
                continue
            if p.get("series_type") != series_type:
                continue
            if series_type.startswith("asset_"):
                qc = p.get("quote_currency")
                if not isinstance(qc, str) or qc.lower() != vs_currency_n:
                    continue
            candidates.append(p)
        if not candidates:
            return None
        def key(p):
            src = (p.get("source") or "").lower()
            internal = 1 if src == "internal_aggregated" else 0
            qs = p.get("quality_score")
            try:
                qs_v = float(qs) if qs is not None else -1.0
            except Exception:
                qs_v = -1.0
            ts = _parse_dt2(p.get("bucket_start_at")) or _parse_dt2(p.get("updated_at")) or _parse_dt2(p.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            return (internal, qs_v, ts)
        candidates.sort(key=key, reverse=True)
        return candidates[0]

    rows = []
    resolved_any = False
    for q in assets_in:
        a = _resolve_asset(q)
        if not a:
            rows.append({"query": q, "resolved": False, "error": "unresolved"})
            continue
        resolved_any = True
        aid = a.get("id")
        price_p = _best_point(aid, "asset_price")
        vol_p = _best_point(aid, "asset_volume")
        mc_p = _best_point(aid, "asset_market_cap")

        aux = price_p.get("aux") if isinstance(price_p, dict) else {}
        if not isinstance(aux, dict):
            aux = {}

        def _aux_get(*keys):
            for k in keys:
                if k in aux:
                    return aux.get(k)
            return None

        row = {
            "query": q,
            "resolved": True,
            "asset": a,
            "as_of": price_p.get("bucket_start_at") if isinstance(price_p, dict) else None,
            "source": price_p.get("source") if isinstance(price_p, dict) else None,
            "price": price_p.get("value") if isinstance(price_p, dict) else None,
            "market_cap": _aux_get("market_cap", "market_cap_usd", f"market_cap_{vs_currency_n}") if isinstance(price_p, dict) else None,
            "volume": _aux_get("volume", "volume_usd", f"volume_{vs_currency_n}") if isinstance(price_p, dict) else None,
            "change_24h": _aux_get("change_24h", "change_24h_pct", "price_change_24h", "price_change_24h_pct") if isinstance(price_p, dict) else None
        }
        if row["market_cap"] is None and isinstance(mc_p, dict):
            row["market_cap"] = mc_p.get("value")
        if row["volume"] is None and isinstance(vol_p, dict):
            row["volume"] = vol_p.get("value")
        rows.append(row)

    if not resolved_any:
        _log("error", meta={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "None of the provided assets could be resolved")

    def _sort_key(r):
        if not isinstance(r, dict) or not r.get("resolved"):
            return (1, None)
        v = r.get(sort_by)
        if v is None:
            return (1, None)
        try:
            fv = float(v)
        except Exception:
            return (1, None)
        return (0, -fv)  # descending numeric

    rows_sorted = sorted(rows, key=_sort_key)
    out = {"vs_currency": vs_currency_n, "sort_by": sort_by, "results": rows_sorted, "count": len(rows_sorted)}
    _log("ok", meta={"count": len(rows_sorted), "resolved_any": resolved_any})
    return out

def get_historical_price(asset, start_date=None, end_date=None, granularity=None, vs_currency=None, include_volume=None, include_market_cap=None, sources=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_historical_price"
    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _parse_date_yyyy_mm_dd(s):
        try:
            return datetime.datetime.strptime(s, "%Y-%m-%d").date()
        except Exception:
            return None

    def _stable_hash(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _log(status, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        logs.append({
            "id": "req_" + _stable_hash(f"{endpoint}|{now.isoformat()}|{len(logs)}")[:24],
            "endpoint": endpoint,
            "tool_name": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now.isoformat(),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Rate limit
    logs0 = _load("request_logs.json")
    if isinstance(logs0, list):
        now = _now_utc()
        cutoff = now - datetime.timedelta(seconds=60)
        recent = 0
        for r in reversed(logs0[-5000:]):
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if ts < cutoff:
                break
            recent += 1
        if recent >= 240:
            _log("error", meta={"error_code": "RATE_LIMIT"})
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")

    # Validate inputs
    if not isinstance(asset, str) or not asset.strip():
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "asset must be a non-empty string")

    if vs_currency is None:
        vs_currency = "usd"
    if not isinstance(vs_currency, str) or not vs_currency.strip():
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "vs_currency must be a non-empty string")
    vs_currency_n = vs_currency.strip().lower()

    if granularity is None:
        granularity = "daily"
    if not isinstance(granularity, str) or granularity not in ("hourly", "daily", "weekly", "monthly"):
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "granularity must be one of: hourly, daily, weekly, monthly")

    if include_volume is None:
        include_volume = True
    if include_market_cap is None:
        include_market_cap = True
    if not isinstance(include_volume, bool) or not isinstance(include_market_cap, bool):
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_volume and include_market_cap must be booleans")

    allowed_sources = ("coingecko", "cmc", "defillama", "internal_aggregated")
    sources_n = None
    if sources is not None:
        if not isinstance(sources, list) or any((not isinstance(x, str) or not x.strip()) for x in sources):
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "sources must be an array of non-empty strings")
        sources_n = [s.strip().lower() for s in sources]
        bad = [s for s in sources_n if s not in allowed_sources]
        if bad:
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Unknown sources value(s)", sources=bad, allowed=list(allowed_sources))

    today = _now_utc().date()
    if start_date is None:
        start_d = today - datetime.timedelta(days=30)
    else:
        if not isinstance(start_date, str) or not start_date.strip():
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "start_date must be YYYY-MM-DD")
        start_d = _parse_date_yyyy_mm_dd(start_date.strip())
        if not start_d:
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "start_date must be YYYY-MM-DD")

    if end_date is None:
        end_d = today
    else:
        if not isinstance(end_date, str) or not end_date.strip():
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "end_date must be YYYY-MM-DD")
        end_d = _parse_date_yyyy_mm_dd(end_date.strip())
        if not end_d:
            _log("error", meta={"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "end_date must be YYYY-MM-DD")

    if start_d > end_d:
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "start_date must be <= end_date", start_date=str(start_d), end_date=str(end_d))

    assets_rows = _load("assets.json")
    if not isinstance(assets_rows, list):
        assets_rows = []

    q = asset.strip()
    q_low = q.lower()
    is_addr = bool(re.fullmatch(r"0x[a-fA-F0-9]{40}", q))
    addr_n = q_low if is_addr else None

    def _norm_slug(s):
        s = (s or "").strip().lower()
        s = re.sub(r"\s+", "-", s)
        s = re.sub(r"[^a-z0-9\-]+", "", s)
        return s or None

    def _resolve_asset(query_str):
        # allow direct id
        for a in assets_rows:
            if isinstance(a, dict) and a.get("status") == "active" and a.get("id") == query_str:
                return a
        if addr_n:
            matches = [a for a in assets_rows if isinstance(a, dict) and a.get("status") == "active" and isinstance(a.get("contract_address"), str) and a.get("contract_address").strip().lower() == addr_n]
            if matches:
                matches.sort(key=lambda r: (0 if r.get("asset_type") == "token" else 1, r.get("id") or ""))
                return matches[0]
        sym = query_str.strip().upper()
        matches = [a for a in assets_rows if isinstance(a, dict) and a.get("status") == "active" and isinstance(a.get("symbol"), str) and a.get("symbol").strip().upper() == sym]
        if matches:
            matches.sort(key=lambda r: (0 if r.get("asset_type") == "cryptocurrency" else 1, r.get("id") or ""))
            return matches[0]
        slug_q = _norm_slug(query_str)
        name_q = query_str.strip().lower()
        matches = []
        for a in assets_rows:
            if not isinstance(a, dict) or a.get("status") != "active":
                continue
            if slug_q and isinstance(a.get("slug"), str) and a.get("slug").strip().lower() == slug_q:
                matches.append(a)
            elif isinstance(a.get("name"), str) and a.get("name").strip().lower() == name_q:
                matches.append(a)
        if matches:
            matches.sort(key=lambda r: (0 if r.get("asset_type") == "cryptocurrency" else 1, r.get("id") or ""))
            return matches[0]
        return None

    resolved = _resolve_asset(q)
    if not resolved:
        # same permissive fallback as get_current_price
        if q_low in ("cryptocurrency", "token", "defi_protocol"):
            tsp0 = _load("timeseries_points.json")
            if not isinstance(tsp0, list):
                tsp0 = []
            counts = {}
            for p in tsp0:
                if isinstance(p, dict) and isinstance(p.get("asset_id"), str) and p.get("asset_id"):
                    counts[p["asset_id"]] = counts.get(p["asset_id"], 0) + 1
            candidates = [a for a in assets_rows if isinstance(a, dict) and a.get("status") == "active"]
            candidates.sort(key=lambda a: (-counts.get(a.get("id"), 0), a.get("id") or ""))
            resolved = candidates[0] if candidates else None

    if not resolved:
        _log("error", meta={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Asset could not be resolved", asset=asset)

    asset_id = resolved.get("id")

    tsp = _load("timeseries_points.json")
    if not isinstance(tsp, list):
        tsp = []

    start_dt = datetime.datetime.combine(start_d, datetime.time.min, tzinfo=datetime.timezone.utc)
    end_dt = datetime.datetime.combine(end_d, datetime.time.max, tzinfo=datetime.timezone.utc)

    def _filter_points(series_type):
        pts = []
        for p in tsp:
            if not isinstance(p, dict):
                continue
            if p.get("series_type") != series_type:
                continue
            if p.get("asset_id") != asset_id:
                continue
            if p.get("granularity") != granularity:
                continue
            qc = p.get("quote_currency")
            if not isinstance(qc, str) or qc.lower() != vs_currency_n:
                continue
            if sources_n is not None:
                src = p.get("source")
                if not isinstance(src, str) or src.lower() not in sources_n:
                    continue
            ts = _parse_dt(p.get("bucket_start_at"))
            if not ts:
                continue
            if ts < start_dt or ts > end_dt:
                continue
            pts.append(p)
        # deterministic order
        pts.sort(key=lambda p: (_parse_dt(p.get("bucket_start_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), (p.get("source") or "")))
        return pts

    price_pts = _filter_points("asset_price")
    vol_pts = _filter_points("asset_volume") if include_volume else []
    mc_pts = _filter_points("asset_market_cap") if include_market_cap else []

    # If multiple sources per bucket, pick best per bucket (internal_aggregated > quality_score > updated_at)
    def _best_per_bucket(points):
        by = {}
        for p in points:
            b = p.get("bucket_start_at")
            if not isinstance(b, str):
                continue
            cur = by.get(b)
            if cur is None:
                by[b] = p
                continue
            def score(x):
                src = (x.get("source") or "").lower()
                internal = 1 if src == "internal_aggregated" else 0
                qs = x.get("quality_score")
                try:
                    qs_v = float(qs) if qs is not None else -1.0
                except Exception:
                    qs_v = -1.0
                ts = _parse_dt(x.get("updated_at")) or _parse_dt(x.get("created_at")) or _parse_dt(x.get("bucket_start_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
                return (internal, qs_v, ts)
            if score(p) > score(cur):
                by[b] = p
        out = list(by.values())
        out.sort(key=lambda p: _parse_dt(p.get("bucket_start_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc))
        return out

    price_best = _best_per_bucket(price_pts)
    vol_best = _best_per_bucket(vol_pts) if include_volume else []
    mc_best = _best_per_bucket(mc_pts) if include_market_cap else []

    # Cap and downsample policy
    MAX_POINTS = 2000
    def _downsample(points):
        n = len(points)
        if n <= MAX_POINTS:
            return points
        step = max(1, n // MAX_POINTS)
        return [p for i, p in enumerate(points) if i % step == 0][:MAX_POINTS]

    price_best = _downsample(price_best)
    vol_map = {p.get("bucket_start_at"): p for p in _downsample(vol_best)} if include_volume else {}
    mc_map = {p.get("bucket_start_at"): p for p in _downsample(mc_best)} if include_market_cap else {}

    series = []
    for p in price_best:
        b = p.get("bucket_start_at")
        aux = p.get("aux")
        if not isinstance(aux, dict):
            aux = {}
        row = {
            "bucket_start_at": b,
            "granularity": granularity,
            "source": p.get("source"),
            "price": p.get("value"),
            "aux": aux
        }
        if include_volume:
            vp = vol_map.get(b)
            row["volume"] = vp.get("value") if isinstance(vp, dict) else None
        if include_market_cap:
            mp = mc_map.get(b)
            row["market_cap"] = mp.get("value") if isinstance(mp, dict) else None
        series.append(row)

    out = {
        "asset": resolved,
        "vs_currency": vs_currency_n,
        "start_date": str(start_d),
        "end_date": str(end_d),
        "granularity": granularity,
        "points": series,
        "meta": {"returned_points": len(series), "max_points": MAX_POINTS}
    }
    _log("ok", meta={"asset_id": asset_id, "returned_points": len(series)})
    return out

def get_price_analytics(asset, period=None, vs_currency=None, include_technical_indicators=None, **_extra):
    import json, os, datetime, time, hashlib, math, statistics, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_price_analytics"
    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _stable_hash(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _log(status_s, meta=None, credential_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        logs.append({
            "id": "req_" + _stable_hash(f"{endpoint}|{now.isoformat()}|{len(logs)}")[:24],
            "endpoint": endpoint,
            "tool_name": endpoint,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now.isoformat(),
            "credential_id": credential_id,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Rate limit (global, since tool has no explicit auth param)
    try:
        logs0 = _load("request_logs.json")
        if isinstance(logs0, list):
            now = _now_utc()
            cutoff = now - datetime.timedelta(seconds=60)
            recent = 0
            for r in reversed(logs0[-5000:]):
                ts = _parse_dt(r.get("timestamp"))
                if not ts:
                    continue
                if ts < cutoff:
                    break
                recent += 1
            if recent >= 240:
                _log("error", meta={"error_code": "RATE_LIMIT"})
                return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
    except Exception:
        # If logs malformed, do not block service
        pass

    # Validate inputs
    if not isinstance(asset, str) or not asset.strip():
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "asset must be a non-empty string.")
    asset_q = asset.strip()

    allowed_periods = {"7d": 7, "30d": 30, "90d": 90, "1y": 365}
    if period is None:
        period = "30d"
    if not isinstance(period, str) or period not in allowed_periods:
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Unsupported period. Must be one of: 7d, 30d, 90d, 1y.")
    days = allowed_periods[period]

    if vs_currency is None:
        vs_currency = "usd"
    if not isinstance(vs_currency, str) or not vs_currency.strip():
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "vs_currency must be a non-empty string.")
    vs = vs_currency.strip().lower()
    # Parameter schema mentions usd/eur/btc. Accept other strings but normalize.
    if not re.fullmatch(r"[a-z0-9]{2,15}", vs):
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "vs_currency must be a simple currency code (e.g., usd, eur, btc).")

    if include_technical_indicators is None:
        include_technical_indicators = False
    if not isinstance(include_technical_indicators, bool):
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_technical_indicators must be boolean.")

    # Resolve asset like get_current_price: contract_address+chain first (if supplied in query), else symbol, else name/slug.
    assets = _load("assets.json")
    if isinstance(assets, dict) and "rows" in assets and isinstance(assets["rows"], list):
        assets = assets["rows"]
    if not isinstance(assets, list):
        assets = []

    def _norm_addr(s):
        if not isinstance(s, str):
            return None
        s = s.strip().lower()
        if s.startswith("0x") and re.fullmatch(r"0x[a-f0-9]{40}", s):
            return s
        return None

    def _norm_sym(s):
        if not isinstance(s, str):
            return None
        s = s.strip()
        if not s:
            return None
        return s.upper()

    def _norm_slug(s):
        if not isinstance(s, str):
            return None
        s = s.strip().lower()
        if not s:
            return None
        return re.sub(r"\s+", "-", s)

    # Parse "chain:address" or "address@chain" or "chain address"
    chain_hint = None
    addr_hint = _norm_addr(asset_q)
    if addr_hint is None:
        m = re.match(r"^\s*([A-Za-z0-9][A-Za-z0-9 \-_]{1,40})[:@]\s*(0x[a-fA-F0-9]{40})\s*$", asset_q)
        if m:
            chain_hint = m.group(1).strip()
            addr_hint = _norm_addr(m.group(2))
        else:
            m2 = re.match(r"^\s*(0x[a-fA-F0-9]{40})\s+([A-Za-z0-9][A-Za-z0-9 \-_]{1,40})\s*$", asset_q)
            if m2:
                addr_hint = _norm_addr(m2.group(1))
                chain_hint = m2.group(2).strip()

    asset_row = None
    if addr_hint:
        # match requires chain for uniqueness constraint; if not provided, allow any exact address match (best effort)
        candidates = []
        for a in assets:
            if not isinstance(a, dict):
                continue
            if a.get("status") != "active":
