            ca = a.get("contract_address")
            if isinstance(ca, str) and ca.strip().lower() == addr_hint:
                if chain_hint:
                    pc = a.get("primary_chain")
                    if isinstance(pc, str) and pc.strip().lower() == chain_hint.strip().lower():
                        candidates.append(a)
                else:
                    candidates.append(a)
        if candidates:
            asset_row = candidates[0]

    if asset_row is None:
        sym = _norm_sym(asset_q)
        if sym:
            for a in assets:
                if not isinstance(a, dict):
                    continue
                if a.get("status") != "active":
                    continue
                if isinstance(a.get("symbol"), str) and a.get("symbol").strip().upper() == sym:
