    if asset_row is None:
        qn = asset_q.strip().lower()
        qslug = _norm_slug(asset_q)
        for a in assets:
            if not isinstance(a, dict):
                continue
            if a.get("status") != "active":
                continue
            nm = a.get("name")
            sg = a.get("slug")
            if isinstance(nm, str) and nm.strip().lower() == qn:
                asset_row = a
                break
            if qslug and isinstance(sg, str) and sg.strip().lower() == qslug:
                asset_row = a
                break

    if not asset_row:
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid asset: could not resolve to an active asset record.")

    asset_id = asset_row.get("id")

    # Pull historical points for period from timeseries_points
    tsp = _load("timeseries_points.json")
    if isinstance(tsp, dict) and "rows" in tsp and isinstance(tsp["rows"], list):
        tsp = tsp["rows"]
    if not isinstance(tsp, list):
        tsp = []

    now = _now_utc()
    start = now - datetime.timedelta(days=days)

    price_points = []
    for p in tsp:
        if not isinstance(p, dict):
            continue
        if p.get("series_type") != "asset_price":
            continue
        if p.get("asset_id") != asset_id:
            continue
        qc = p.get("quote_currency")
        if not isinstance(qc, str) or qc.strip().lower() != vs:
            continue
        if p.get("status") == "invalid":
            continue
        dt = _parse_dt(p.get("bucket_start_at"))
        if not dt:
            continue
        if dt < start or dt > now:
            continue
        v = p.get("value")
        if not isinstance(v, (int, float)):
            continue
        price_points.append((dt, float(v), p))

    # If none for requested vs, try to fall back to any quote currency (to avoid false conflicts),
    # but label it. This matches "relax check stricter than parameter schema".
    used_vs = vs
    if not price_points:
        fallback = []
        for p in tsp:
            if not isinstance(p, dict):
                continue
            if p.get("series_type") != "asset_price":
                continue
            if p.get("asset_id") != asset_id:
                continue
            if p.get("status") == "invalid":
                continue
            dt = _parse_dt(p.get("bucket_start_at"))
            if not dt:
                continue
            if dt < start or dt > now:
                continue
            v = p.get("value")
            qc = p.get("quote_currency")
            if not isinstance(v, (int, float)) or not isinstance(qc, str) or not qc.strip():
                continue
            fallback.append((dt, float(v), p, qc.strip().lower()))
        if fallback:
            # choose quote currency with most points
            counts = {}
            for _, __, ___, qcc in fallback:
                counts[qcc] = counts.get(qcc, 0) + 1
            used_vs = sorted(counts.items(), key=lambda x: (-x[1], x[0]))[0][0]
            price_points = [(dt, v, p) for (dt, v, p, qcc) in fallback if qcc == used_vs]

    price_points.sort(key=lambda x: x[0])

    # Real behavior: do not throw CONFLICT for insufficient data; return analytics with warnings.
    warnings = []
    if used_vs != vs:
        warnings.append(f"No {vs} price points available for period; analytics computed using {used_vs} prices instead.")

    if len(price_points) < 2:
        # Return minimal analytics envelope rather than error
        _log("ok", meta={"asset_id": asset_id, "points": len(price_points)})
        last_price = price_points[-1][1] if price_points else None
        return {
            "asset_id": asset_id,
            "asset": {
                "id": asset_row.get("id"),
                "symbol": asset_row.get("symbol"),
                "name": asset_row.get("name"),
