                "asset_type": asset_row.get("asset_type"),
                "primary_chain": asset_row.get("primary_chain"),
                "contract_address": asset_row.get("contract_address"),
            },
            "period": period,
            "vs_currency": vs,
            "effective_vs_currency": used_vs,
            "data_points": len(price_points),
            "as_of": now.isoformat(),
            "analytics": {
                "last_price": last_price,
                "return_pct": None,
                "volatility_annualized": None,
                "trend": None
            },
            "technical_indicators": None,
            "warnings": warnings + (["Insufficient historical price data for requested period."] if len(price_points) < 2 else []),
        }

    # Compute returns and volatility
    prices = [v for _, v, __ in price_points]
    times = [dt for dt, _, __ in price_points]
    first = prices[0]
    last = prices[-1]
    ret_pct = None
    if first and first > 0:
        ret_pct = (last / first - 1.0) * 100.0

    # log returns
    log_returns = []
    for i in range(1, len(prices)):
        p0, p1 = prices[i-1], prices[i]
        if p0 > 0 and p1 > 0:
            log_returns.append(math.log(p1 / p0))

    vol_ann = None
    if len(log_returns) >= 2:
        stdev = statistics.pstdev(log_returns) if len(log_returns) > 1 else 0.0
        # approximate annualization based on median delta in days
        deltas = []
        for i in range(1, len(times)):
            deltas.append(max((times[i] - times[i-1]).total_seconds(), 1.0))
        median_sec = statistics.median(deltas) if deltas else 86400.0
        periods_per_year = (365.0 * 86400.0) / median_sec
        vol_ann = stdev * math.sqrt(periods_per_year)
    else:
        warnings.append("Too few valid consecutive price points to compute volatility reliably.")

    # Trend summary: simple slope on normalized time index
    trend = None
    try:
        xs = list(range(len(prices)))
        x_mean = sum(xs) / len(xs)
        y_mean = sum(prices) / len(prices)
        num = sum((x - x_mean) * (y - y_mean) for x, y in zip(xs, prices))
        den = sum((x - x_mean) ** 2 for x in xs) or 0.0
        slope = (num / den) if den else 0.0
        if slope > 0:
            trend = "up"
        elif slope < 0:
            trend = "down"
        else:
            trend = "flat"
    except Exception:
        trend = None

    tech = None
    if include_technical_indicators:
        # Need enough points; if not, do not error; omit with warning.
        if len(prices) < 20:
            warnings.append("include_technical_indicators requested but insufficient data points (need >= 20).")
            tech = None
        else:
            window = 14
            # SMA(14)
            sma14 = sum(prices[-window:]) / window if len(prices) >= window else None

            # RSI(14) on simple gains/losses
            gains = []
            losses = []
            for i in range(1, window + 1):
                d = prices[-i] - prices[-i - 1]
                if d >= 0:
                    gains.append(d)
                    losses.append(0.0)
                else:
                    gains.append(0.0)
                    losses.append(-d)
            avg_gain = sum(gains) / window
            avg_loss = sum(losses) / window
            if avg_loss == 0:
                rsi14 = 100.0
            else:
                rs = avg_gain / avg_loss
                rsi14 = 100.0 - (100.0 / (1.0 + rs))

            # Bollinger Bands(20, 2)
            bw = 20
            bb_mid = sum(prices[-bw:]) / bw
            bb_std = statistics.pstdev(prices[-bw:])
            bb_upper = bb_mid + 2.0 * bb_std
            bb_lower = bb_mid - 2.0 * bb_std

            tech = {
                "sma_14": sma14,
                "rsi_14": rsi14,
                "bollinger_20_2": {"mid": bb_mid, "upper": bb_upper, "lower": bb_lower}
            }

    out = {
        "asset_id": asset_id,
        "asset": {
            "id": asset_row.get("id"),
            "symbol": asset_row.get("symbol"),
            "name": asset_row.get("name"),
            "slug": asset_row.get("slug"),
            "asset_type": asset_row.get("asset_type"),
            "primary_chain": asset_row.get("primary_chain"),
            "contract_address": asset_row.get("contract_address"),
        },
        "period": period,
        "vs_currency": vs,
        "effective_vs_currency": used_vs,
        "data_points": len(price_points),
        "window_start": start.isoformat(),
        "window_end": now.isoformat(),
        "analytics": {
            "first_price": first,
            "last_price": last,
            "return_pct": ret_pct,
            "volatility_annualized": vol_ann,
            "trend": trend,
        },
        "technical_indicators": tech,
        "warnings": warnings
    }
    _log("ok", meta={"asset_id": asset_id, "points": len(price_points), "include_technical_indicators": include_technical_indicators})
    return out

def search_assets(query, category=None, asset_type=None, limit=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, latency_ms, details=None):
        if details is None:
            details = {}
        fname = "request_logs.json"
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            return
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": _now_iso(),
            "details": details
        })
        _save(fname, logs)

    # Validate
    if not isinstance(query, str):
        _log("search_assets", "VALIDATION_ERROR", (time.time() - _t0) * 1000, {"reason": "query_type"})
        return _err("VALIDATION_ERROR", "query must be a string")
    q = query.strip()
    if not q:
        _log("search_assets", "VALIDATION_ERROR", (time.time() - _t0) * 1000, {"reason": "query_empty"})
        return _err("VALIDATION_ERROR", "query must be non-empty after trimming")

    if limit is None:
        limit = 10
    # schema says number; accept ints/floats but must be integer-like
    if not isinstance(limit, (int, float)) or (isinstance(limit, float) and not limit.is_integer()):
        _log("search_assets", "VALIDATION_ERROR", (time.time() - _t0) * 1000, {"reason": "limit_type"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50")
    limit = int(limit)
    if limit < 1 or limit > 50:
        _log("search_assets", "VALIDATION_ERROR", (time.time() - _t0) * 1000, {"reason": "limit_range", "limit": limit})
        return _err("VALIDATION_ERROR", "limit must be within [1,50]")

    if category is not None:
        if not isinstance(category, str) or not category.strip():
            _log("search_assets", "VALIDATION_ERROR", (time.time() - _t0) * 1000, {"reason": "category"})
            return _err("VALIDATION_ERROR", "category must be a non-empty string when provided")
        cat = category.strip().lower()
    else:
        cat = None

    if asset_type is not None:
        if not isinstance(asset_type, str):
            _log("search_assets", "VALIDATION_ERROR", (time.time() - _t0) * 1000, {"reason": "asset_type_type"})
            return _err("VALIDATION_ERROR", "asset_type must be a string")
        if asset_type not in ("cryptocurrency", "token", "defi_protocol"):
            _log("search_assets", "VALIDATION_ERROR", (time.time() - _t0) * 1000, {"reason": "asset_type_enum"})
            return _err("VALIDATION_ERROR", "Unsupported asset_type", allowed=["cryptocurrency", "token", "defi_protocol"])
        at = asset_type
    else:
        at = None

    assets_rows = _load("assets.json")
    if not isinstance(assets_rows, list):
        assets_rows = []

    ql = q.lower()
    qu = q.upper()

    def _text_fields(a):
        fields = []
        for k in ("symbol", "name", "slug"):
            v = a.get(k)
            if isinstance(v, str) and v.strip():
                fields.append(v.strip())
        pids = a.get("provider_ids")
        if isinstance(pids, dict):
            for _, v in pids.items():
                if isinstance(v, str) and v.strip():
                    fields.append(v.strip())
        cats = a.get("categories")
        if isinstance(cats, list):
            for c in cats:
                if isinstance(c, str) and c.strip():
                    fields.append(c.strip())
        return fields

    def _match_score(a):
        # Higher better. Prefer exact symbol, then prefix, then substring.
        score = 0
        sym = a.get("symbol")
        if isinstance(sym, str):
            s = sym.strip().upper()
            if s == qu:
                score += 100
            elif s.startswith(qu):
                score += 60
            elif qu in s:
                score += 30
        nm = a.get("name")
        if isinstance(nm, str):
            n = nm.strip().lower()
            if n == ql:
                score += 80
            elif n.startswith(ql):
                score += 40
            elif ql in n:
                score += 20
        sl = a.get("slug")
        if isinstance(sl, str):
            s = sl.strip().lower()
            if s == ql:
                score += 70
            elif s.startswith(ql):
                score += 35
            elif ql in s:
                score += 15
        pids = a.get("provider_ids")
        if isinstance(pids, dict):
            for _, v in pids.items():
                if isinstance(v, str):
                    vv = v.strip().lower()
                    if vv == ql:
                        score += 50
                    elif ql in vv:
                        score += 10
        cats = a.get("categories")
        if isinstance(cats, list):
            for c in cats:
                if isinstance(c, str) and c.strip().lower() == ql:
                    score += 25
        return score

    matches = []
    for a in assets_rows:
        if a.get("status") != "active":
            continue
        if at is not None and a.get("asset_type") != at:
            continue
        if cat is not None:
            cats = a.get("categories")
            if not (isinstance(cats, list) and any(isinstance(c, str) and c.strip().lower() == cat for c in cats)):
                continue
        # must match by symbol/name/slug/provider_ids/categories per rules
        texts = _text_fields(a)
        ok = False
        for t in texts:
            tl = t.lower()
            tu = t.upper()
            if ql in tl or qu in tu:
                ok = True
                break
        if not ok:
            continue
        matches.append((-_match_score(a), a.get("name") or "", a.get("id") or "", a))

    matches.sort()
    out = []
    for _, _, _, a in matches[:limit]:
        out.append({
            "id": a.get("id"),
            "asset_type": a.get("asset_type"),
            "symbol": a.get("symbol"),
            "name": a.get("name"),
            "slug": a.get("slug"),
            "primary_chain": a.get("primary_chain"),
            "contract_address": a.get("contract_address"),
            "categories": a.get("categories") if isinstance(a.get("categories"), list) else [],
            "provider_ids": a.get("provider_ids") if isinstance(a.get("provider_ids"), dict) else {}
        })

    resp = {
        "query": q,
        "category": cat,
        "asset_type": at,
        "limit": limit,
        "results": out,
        "meta": {"returned": len(out)}
    }
    _log("search_assets", "OK", (time.time() - _t0) * 1000, {"returned": len(out)})
    return resp

def get_assets_by_category(category, include_prices=None, vs_currency=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, latency_ms, details=None):
        if details is None:
            details = {}
        fname = "request_logs.json"
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            return
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": _now_iso(),
            "details": details
        })
        _save(fname, logs)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1]
            for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S", "%Y-%m-%d"):
                try:
                    return datetime.datetime.strptime(s, fmt)
                except Exception:
                    pass
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    # Validate
    if not isinstance(category, str) or not category.strip():
        _log("get_assets_by_category", "VALIDATION_ERROR", (time.time() - _t0) * 1000, {"reason": "category"})
        return _err("VALIDATION_ERROR", "category is required and must be a non-empty string")
    cat = category.strip().lower()

    if include_prices is None:
        include_prices = True
    if vs_currency is None:
        vs_currency = "usd"

    if not isinstance(include_prices, bool):
        _log("get_assets_by_category", "VALIDATION_ERROR", (time.time() - _t0) * 1000, {"reason": "include_prices"})
        return _err("VALIDATION_ERROR", "include_prices must be boolean")
    if not isinstance(vs_currency, str) or not vs_currency.strip():
        _log("get_assets_by_category", "VALIDATION_ERROR", (time.time() - _t0) * 1000, {"reason": "vs_currency"})
        return _err("VALIDATION_ERROR", "vs_currency must be a non-empty string")
    vs_currency = vs_currency.strip().lower()

    assets_rows = _load("assets.json")
    if not isinstance(assets_rows, list):
        assets_rows = []

    matched = []
    for a in assets_rows:
        if a.get("status") != "active":
            continue
        cats = a.get("categories")
        if not isinstance(cats, list):
            continue
        if any(isinstance(c, str) and c.strip().lower() == cat for c in cats):
            matched.append(a)

    if not matched:
        _log("get_assets_by_category", "NOT_FOUND", (time.time() - _t0) * 1000, {"reason": "no_assets"})
        return _err("NOT_FOUND", "Category not found or has no assets", category=cat)

    # Optionally attach latest price
    price_map = {}
    if include_prices:
        points = _load("timeseries_points.json")
        if not isinstance(points, list):
            points = []

        # Index latest per asset_id, prefer internal_aggregated else best quality
        for p in points:
            if p.get("series_type") != "asset_price":
                continue
            aid = p.get("asset_id")
            if not aid:
                continue
            if (p.get("quote_currency") or "").strip().lower() != vs_currency:
                continue
            dt = _parse_dt(p.get("bucket_start_at"))
            if dt is None:
                continue
            cur = price_map.get(aid)
            if cur is None:
                price_map[aid] = p
            else:
                def _rank(x):
                    src = x.get("source")
                    src_rank = 2 if src == "internal_aggregated" else 1
                    qs = x.get("quality_score")
                    qs_val = qs if isinstance(qs, (int, float)) else -1.0
                    bt = _parse_dt(x.get("bucket_start_at")) or datetime.datetime.min
                    return (src_rank, qs_val, bt)
                if _rank(p) > _rank(cur):
                    price_map[aid] = p

    out = []
    for a in matched:
        row = {
            "id": a.get("id"),
            "asset_type": a.get("asset_type"),
            "symbol": a.get("symbol"),
            "name": a.get("name"),
            "slug": a.get("slug"),
            "primary_chain": a.get("primary_chain"),
            "contract_address": a.get("contract_address"),
            "categories": a.get("categories") if isinstance(a.get("categories"), list) else [],
            "provider_ids": a.get("provider_ids") if isinstance(a.get("provider_ids"), dict) else {}
        }
        if include_prices:
            p = price_map.get(a.get("id"))
            if p:
                row["price"] = {
                    "vs_currency": vs_currency,
                    "value": p.get("value"),
                    "source": p.get("source"),
                    "bucket_start_at": p.get("bucket_start_at"),
                    "quality_score": p.get("quality_score"),
                    "status": p.get("status")
                }
            else:
                row["price"] = None
        out.append(row)

    # Stable order: symbol/name
    def _k(r):
        sym = r.get("symbol") or ""
        nm = r.get("name") or ""
        return (sym, nm, r.get("id") or "")
    out.sort(key=_k)

    resp = {
        "category": cat,
        "vs_currency": vs_currency,
        "include_prices": include_prices,
        "assets": out,
        "meta": {"returned": len(out)}
    }
    _log("get_assets_by_category", "OK", (time.time() - _t0) * 1000, {"returned": len(out), "include_prices": include_prices})
    return resp

