def list_assets(api_key, status=None, asset_type=None, category=None, symbol=None, primary_chain=None, contract_address=None, provider=None, limit=None, cursor=None, order_by=None, order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_assets"
    used_cred = None

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_str, error_code=None, error_message=None):
        # Schema declares no request-log collection; do not persist logs.
        return

    # Validate api_key
    if not isinstance(api_key, str) or not api_key.strip():
        _log("error", "VALIDATION_ERROR", "api_key must be a non-empty string")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    # No credentials collection provided. Authenticate ambiently: accept any non-empty key.
    used_cred = api_key.strip()

    # Validate filters/pagination
    allowed_status = {"active", "deprecated", "disabled"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log("error", "VALIDATION_ERROR", "Invalid status")
            return _err("VALIDATION_ERROR", "status must be one of: active, deprecated, disabled")

    # Tool enum differs from datastore's asset_type; enforce tool's enum and map to datastore.
    tool_asset_types = {"coin", "token", "stablecoin", "nft", "index", "other"}
    asset_type_map = {
        "coin": "cryptocurrency",
        "token": "token",
        "stablecoin": "token",
        "nft": "token",
        "index": "token",
        "other": "defi_protocol",
    }
    if asset_type is not None:
        if not isinstance(asset_type, str) or asset_type not in tool_asset_types:
            _log("error", "VALIDATION_ERROR", "Invalid asset_type")
            return _err("VALIDATION_ERROR", "asset_type must be one of: coin, token, stablecoin, nft, index, other")

    if category is not None and not isinstance(category, str):
        _log("error", "VALIDATION_ERROR", "category must be a string")
        return _err("VALIDATION_ERROR", "category must be a string")

    if symbol is not None and not isinstance(symbol, str):
        _log("error", "VALIDATION_ERROR", "symbol must be a string")
        return _err("VALIDATION_ERROR", "symbol must be a string")

    if primary_chain is not None and not isinstance(primary_chain, str):
        _log("error", "VALIDATION_ERROR", "primary_chain must be a string")
        return _err("VALIDATION_ERROR", "primary_chain must be a string")

    if contract_address is not None and not isinstance(contract_address, str):
        _log("error", "VALIDATION_ERROR", "contract_address must be a string")
        return _err("VALIDATION_ERROR", "contract_address must be a string")

    allowed_provider = {"coingecko", "defillama", "internal"}
    if provider is not None:
        if not isinstance(provider, str) or provider not in allowed_provider:
            _log("error", "VALIDATION_ERROR", "Invalid provider")
            return _err("VALIDATION_ERROR", "provider must be one of: coingecko, defillama, internal")

    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        _log("error", "VALIDATION_ERROR", "limit out of range")
        return _err("VALIDATION_ERROR", "limit must be an integer within [1, 50]")

    allowed_order_by = {"created_at", "updated_at", "symbol", "name"}
    if order_by is None:
        order_by = "updated_at"
    if not isinstance(order_by, str) or order_by not in allowed_order_by:
        _log("error", "VALIDATION_ERROR", "Invalid order_by")
        return _err("VALIDATION_ERROR", "order_by must be one of: created_at, updated_at, symbol, name")

    allowed_order = {"asc", "desc"}
    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in allowed_order:
        _log("error", "VALIDATION_ERROR", "Invalid order")
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc")

    # Cursor decoding: base64url(json({"v":1,"o":order_by,"d":order,"k":[sort_value, id]}))
    start_after = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log("error", "VALIDATION_ERROR", "cursor must be a string")
            return _err("VALIDATION_ERROR", "cursor must be a string")
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or obj.get("v") != 1 or obj.get("o") != order_by or obj.get("d") != order:
                _log("error", "VALIDATION_ERROR", "Invalid cursor for this sort")
                return _err("VALIDATION_ERROR", "cursor is invalid for the requested order_by/order")
            k = obj.get("k")
            if (not isinstance(k, list)) or len(k) != 2 or not isinstance(k[1], str):
                _log("error", "VALIDATION_ERROR", "Invalid cursor shape")
                return _err("VALIDATION_ERROR", "cursor is invalid")
            start_after = (k[0], k[1])
        except (ValueError, json.JSONDecodeError, UnicodeDecodeError):
            _log("error", "VALIDATION_ERROR", "Cursor decode failed")
            return _err("VALIDATION_ERROR", "cursor is invalid")

    assets = _load("assets.json")

    def _norm_s(x):
        return (x or "").strip()

    def _as_key(v):
        # Keep deterministic ordering across mixed/None values
        if v is None:
            return ""
        if isinstance(v, str):
            return v
        return str(v)

    # Apply filters
    out = []
    cat_norm = _norm_s(category).lower() if category is not None else None
    sym_norm = _norm_s(symbol).upper() if symbol is not None else None
    chain_norm = _norm_s(primary_chain).lower() if primary_chain is not None else None
    addr_norm = _norm_s(contract_address).lower() if contract_address is not None else None
    mapped_type = asset_type_map.get(asset_type) if asset_type is not None else None

    for a in assets:
        if not isinstance(a, dict):
            continue
        if status is not None and a.get("status") != status:
            continue
        if mapped_type is not None and a.get("asset_type") != mapped_type:
            continue
        if cat_norm is not None:
            cats = a.get("categories")
            if not isinstance(cats, list) or all((not isinstance(c, str) or c.strip().lower() != cat_norm) for c in cats):
                continue
        if sym_norm is not None:
            if not isinstance(a.get("symbol"), str) or a.get("symbol").strip().upper() != sym_norm:
                continue
        if chain_norm is not None:
            pc = a.get("primary_chain")
            if not isinstance(pc, str) or pc.strip().lower() != chain_norm:
                continue
        if addr_norm is not None:
            ca = a.get("contract_address")
            if not isinstance(ca, str) or ca.strip().lower() != addr_norm:
                continue
        if provider is not None:
            pids = a.get("provider_ids")
            if not isinstance(pids, dict):
                continue
            if provider == "coingecko":
                if not isinstance(pids.get("coingecko_coin_id"), str) or not pids.get("coingecko_coin_id").strip():
                    continue
            elif provider == "defillama":
                if not isinstance(pids.get("defillama_slug"), str) or not pids.get("defillama_slug").strip():
                    continue
            else:  # internal
                # internal means must have *some* provider id present
                has_any = False
                for v in pids.values():
                    if isinstance(v, str) and v.strip():
                        has_any = True
                        break
                    if isinstance(v, dict) and v:
                        has_any = True
                        break
                if not has_any:
                    continue

        out.append(a)

    # Sort (stable, deterministic) and paginate with tie-breaker id
    reverse = (order == "desc")

    def _sort_tuple(a):
        field = a.get(order_by)
        if order_by in ("symbol", "name"):
            primary = _as_key(field).lower()
        else:
            primary = _as_key(field)
        return (primary, _as_key(a.get("id")))

    out.sort(key=_sort_tuple, reverse=reverse)

    if start_after is not None:
        # Seek past the cursor key
        sa_val, sa_id = start_after
        def _cmp_key(a):
            k = _sort_tuple(a)
            return (k[0], k[1])
        sa = ("" if sa_val is None else str(sa_val).lower() if order_by in ("symbol", "name") else str(sa_val),
              sa_id)
        # Find first element strictly after cursor in the chosen ordering
        filtered = []
        passed = False
        for a in out:
            k0, k1 = _cmp_key(a)
            cur = (k0, k1)
            if not passed:
                if reverse:
                    if cur < sa:
                        passed = True
                else:
                    if cur > sa:
                        passed = True
            if passed:
                filtered.append(a)
        out = filtered

    page_items = out[:limit]
    has_more = len(out) > limit

    next_cursor = None
    if has_more and page_items:
        last = page_items[-1]
        k = _sort_tuple(last)
        payload = {"v": 1, "o": order_by, "d": order, "k": [k[0], k[1]]}
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    _log("ok")
    return {
        "object": "list",
        "data": page_items,
        "meta": {
            "total": len(out) if cursor is not None else len(page_items) + (len(out) - len(page_items)),  # best-effort
            "limit": limit,
            "order_by": order_by,
            "order": order,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def get_asset(api_key, id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    # No credentials store provided; accept any non-empty key as authenticated.
    assets = _load("assets.json")
    target = None
    for a in assets:
        if isinstance(a, dict) and a.get("id") == id:
            target = a
            break

    if target is None:
        return _err("NOT_FOUND", "Asset not found", id=id)

    # "Returns only assets the caller is permitted to view" - no permission model provided; treat as visible.
    return {"object": "asset", "data": target}

def upsert_asset(api_key, id=None, asset_type=None, symbol=None, name=None, slug=None, primary_chain=None, contract_address=None, categories=None, provider_ids=None, status=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "upsert_asset"
    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _stable_hash(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _log(status_s, meta=None, credential_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        logs.append({
            "id": "req_" + _stable_hash(f"{endpoint}|{now.isoformat()}|{len(logs)}")[:24],
            "endpoint": endpoint,
            "tool_name": endpoint,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now.isoformat(),
            "credential_id": credential_id,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Rate limit (global fallback if no per-key usage store exists)
    try:
        logs0 = _load("request_logs.json")
        if isinstance(logs0, list):
            now = _now_utc()
            cutoff = now - datetime.timedelta(seconds=60)
            recent = 0
            for r in reversed(logs0[-5000:]):
                ts = _parse_dt(r.get("timestamp"))
                if not ts:
                    continue
                if ts < cutoff:
                    break
                recent += 1
            if recent >= 240:
                _log("error", meta={"error_code": "RATE_LIMIT"})
                return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
    except Exception:
        pass

    # Validate api_key
    if not isinstance(api_key, str) or not api_key.strip():
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "api_key is required.")

    # Authenticate: match against credential row's client-visible value OR id.
    # Search across plausible credential stores; if none exist, accept ambient auth.
    credential = None
    credential_id = None
    cred_files = ["api_keys.json", "credentials.json", "keys.json"]
    for fn in cred_files:
        rows = _load(fn)
        if isinstance(rows, dict) and "rows" in rows and isinstance(rows["rows"], list):
            rows = rows["rows"]
        if not isinstance(rows, list):
            continue
        for r in rows:
            if not isinstance(r, dict):
                continue
            if r.get("status") and str(r.get("status")) not in ("active", "valid", "enabled"):
                continue
            if api_key == r.get("id") or api_key == r.get("api_key") or api_key == r.get("key") or api_key == r.get("value"):
                credential = r
                credential_id = r.get("id")
                break
        if credential:
            break

    # If a credential store exists but we couldn't match, it's unauthorized.
    cred_store_exists = any(os.path.exists(os.path.join(_DB, fn)) for fn in cred_files)
    if cred_store_exists and not credential:
        _log("error", meta={"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Invalid or revoked credential.")

    # Validate fields per tool schema (accepts broader asset_type than datastore; map to datastore enum)
    if id is not None and (not isinstance(id, str) or not id.strip()):
        _log("error", meta={"error_code": "VALIDATION_ERROR"}, credential_id=credential_id)
        return _err("VALIDATION_ERROR", "id must be a non-empty string when provided.")
    if asset_type is not None and (not isinstance(asset_type, str) or not asset_type.strip()):
        _log("error", meta={"error_code": "VALIDATION_ERROR"}, credential_id=credential_id)
        return _err("VALIDATION_ERROR", "asset_type must be a non-empty string when provided.")
    if symbol is not None and (not isinstance(symbol, str) or not symbol.strip()):
        _log("error", meta={"error_code": "VALIDATION_ERROR"}, credential_id=credential_id)
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string when provided.")
    if name is not None and (not isinstance(name, str) or not name.strip()):
        _log("error", meta={"error_code": "VALIDATION_ERROR"}, credential_id=credential_id)
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided.")
    if slug is not None and (not isinstance(slug, str) or not slug.strip()):
        _log("error", meta={"error_code": "VALIDATION_ERROR"}, credential_id=credential_id)
        return _err("VALIDATION_ERROR", "slug must be a non-empty string when provided.")
    if primary_chain is not None and (not isinstance(primary_chain, str) or not primary_chain.strip()):
        _log("error", meta={"error_code": "VALIDATION_ERROR"}, credential_id=credential_id)
        return _err("VALIDATION_ERROR", "primary_chain must be a non-empty string when provided.")
    if contract_address is not None and (not isinstance(contract_address, str) or not contract_address.strip()):
        _log("error", meta={"error_code": "VALIDATION_ERROR"}, credential_id=credential_id)
        return _err("VALIDATION_ERROR", "contract_address must be a non-empty string when provided.")
    if categories is not None:
        if not isinstance(categories, list) or any((not isinstance(x, str) or not x.strip()) for x in categories):
            _log("error", meta={"error_code": "VALIDATION_ERROR"}, credential_id=credential_id)
            return _err("VALIDATION_ERROR", "categories must be an array of strings.")
    if provider_ids is not None and not isinstance(provider_ids, dict):
        _log("error", meta={"error_code": "VALIDATION_ERROR"}, credential_id=credential_id)
        return _err("VALIDATION_ERROR", "provider_ids must be an object when provided.")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deprecated", "disabled"):
            _log("error", meta={"error_code": "VALIDATION_ERROR"}, credential_id=credential_id)
            return _err("VALIDATION_ERROR", "status must be one of: active, deprecated, disabled.")

    # Load assets
    assets = _load("assets.json")
    wrapper = None
    if isinstance(assets, dict) and "rows" in assets and isinstance(assets["rows"], list):
        wrapper = assets
        assets_rows = assets["rows"]
    elif isinstance(assets, list):
        assets_rows = assets
    else:
        assets_rows = []

    # Helpers for uniqueness constraints + normalization
    def _norm_sym(s):
        return s.strip().upper() if isinstance(s, str) and s.strip() else None

    def _norm_slug(s):
        if not isinstance(s, str):
            return None
        s = s.strip().lower()
        if not s:
            return None
        return re.sub(r"\s+", "-", s)

    def _norm_addr(s):
        if not isinstance(s, str):
            return None
        s = s.strip().lower()
        if not s:
            return None
        return s

    # Map tool asset_type -> datastore asset_type enum
    # datastore: cryptocurrency, token, defi_protocol
    at_in = asset_type.strip().lower() if isinstance(asset_type, str) else None
    at_map = {
        "coin": "cryptocurrency",
        "stablecoin": "token",
        "token": "token",
        "nft": "token",
        "index": "cryptocurrency",
        "other": "token",
    }
    mapped_asset_type = at_map.get(at_in, None) if at_in else None
    if at_in and not mapped_asset_type:
        _log("error", meta={"error_code": "VALIDATION_ERROR"}, credential_id=credential_id)
        return _err("VALIDATION_ERROR", "asset_type is not supported by backend mapping.")

    now = _now_utc().isoformat()

    # Determine if update or create
    existing = None
    if id is not None:
        for a in assets_rows:
            if isinstance(a, dict) and a.get("id") == id:
                existing = a
                break

    # For create, required by schema: name, asset_type, categories, provider_ids, status, created_at, updated_at
    if existing is None:
        if id is None:
            # generate id with convention
            rid = _stable_hash(f"asset|{now}|{len(assets_rows)}")[:26]
            id = "scry_ast_" + datetime.datetime.now(datetime.timezone.utc).strftime("%y%m%d") + "_" + rid
        if not isinstance(name, str) or not name.strip():
            _log("error", meta={"error_code": "VALIDATION_ERROR"}, credential_id=credential_id)
            return _err("VALIDATION_ERROR", "name is required to create a new asset.")
        if mapped_asset_type is None:
            _log("error", meta={"error_code": "VALIDATION_ERROR"}, credential_id=credential_id)
            return _err("VALIDATION_ERROR", "asset_type is required to create a new asset.")
        if categories is None:
            categories = []
        if provider_ids is None:
            provider_ids = {}
        if status is None:
            status = "active"

        # build new record
        rec = {
            "id": id,
            "asset_type": mapped_asset_type,
            "symbol": _norm_sym(symbol) if symbol is not None else None,
            "name": name.strip(),
            "slug": _norm_slug(slug) if slug is not None else _norm_slug(name),
            "primary_chain": primary_chain.strip() if isinstance(primary_chain, str) and primary_chain.strip() else None,
            "contract_address": _norm_addr(contract_address) if contract_address is not None else None,
            "categories": [c.strip() for c in categories] if isinstance(categories, list) else [],
            "provider_ids": provider_ids if isinstance(provider_ids, dict) else {},
            "status": status,
            "created_at": now,
            "updated_at": now
        }
        # Ensure non-null fields for schema
        if rec["categories"] is None:
            rec["categories"] = []
        if rec["provider_ids"] is None:
            rec["provider_ids"] = {}

        # uniqueness checks
        # unique(provider_ids.coingecko_coin_id) where not null
        cg = rec.get("provider_ids", {}).get("coingecko_coin_id") if isinstance(rec.get("provider_ids"), dict) else None
        if isinstance(cg, str) and cg.strip():
            cg0 = cg.strip()
            for a in assets_rows:
                if not isinstance(a, dict):
                    continue
                if a.get("id") == rec["id"]:
                    continue
                pid = a.get("provider_ids") if isinstance(a.get("provider_ids"), dict) else {}
                if pid.get("coingecko_coin_id") == cg0:
                    _log("error", meta={"error_code": "CONFLICT"}, credential_id=credential_id)
                    return _err("CONFLICT", "Provider id conflict: provider_ids.coingecko_coin_id must be unique.", field="provider_ids.coingecko_coin_id", value=cg0, conflicting_id=a.get("id"))

        # unique(lower(contract_address), lower(primary_chain)) where contract_address not null
        if rec.get("contract_address"):
            ca0 = str(rec["contract_address"]).lower()
            ch0 = str(rec.get("primary_chain") or "").lower()
            for a in assets_rows:
                if not isinstance(a, dict):
                    continue
                if a.get("id") == rec["id"]:
                    continue
                if a.get("contract_address") and str(a.get("contract_address")).lower() == ca0 and str(a.get("primary_chain") or "").lower() == ch0:
                    _log("error", meta={"error_code": "CONFLICT"}, credential_id=credential_id)
                    return _err("CONFLICT", "Contract address conflict: (contract_address, primary_chain) must be unique.", field="contract_address", value=rec.get("contract_address"), conflicting_id=a.get("id"))

        # unique(upper(symbol), asset_type) where symbol not null
        if rec.get("symbol"):
            sy0 = str(rec["symbol"]).upper()
            for a in assets_rows:
                if not isinstance(a, dict):
                    continue
                if a.get("id") == rec["id"]:
                    continue
                if a.get("symbol") and str(a.get("symbol")).upper() == sy0 and a.get("asset_type") == rec.get("asset_type"):
                    _log("error", meta={"error_code": "CONFLICT"}, credential_id=credential_id)
                    return _err("CONFLICT", "Symbol conflict: (symbol, asset_type) must be unique.", field="symbol", value=sy0, conflicting_id=a.get("id"))

        assets_rows.append(rec)
        if wrapper is not None:
            wrapper["rows"] = assets_rows
            _save("assets.json", wrapper)
        else:
            _save("assets.json", assets_rows)
        _log("ok", meta={"action": "created", "asset_id": id}, credential_id=credential_id)
        return rec

    # Update existing
    old_status = existing.get("status")
    new_status = status if status is not None else old_status
    transitions = {
        "active": {"deprecated", "disabled"},
        "deprecated": {"active", "disabled"},
        "disabled": {"active"},
    }
    if old_status != new_status:
        if old_status not in transitions or new_status not in transitions.get(old_status, set()):
            _log("error", meta={"error_code": "INVALID_TRANSITION", "from": old_status, "to": new_status}, credential_id=credential_id)
            return _err("INVALID_TRANSITION", "Illegal status transition for asset.", from_status=old_status, to_status=new_status)

    # Apply updates (only provided fields)
    updated = dict(existing)
    if mapped_asset_type is not None:
        updated["asset_type"] = mapped_asset_type
    if symbol is not None:
        updated["symbol"] = _norm_sym(symbol)
    if name is not None:
        updated["name"] = name.strip()
    if slug is not None:
        updated["slug"] = _norm_slug(slug)
    if primary_chain is not None:
        updated["primary_chain"] = primary_chain.strip()
    if contract_address is not None:
        updated["contract_address"] = _norm_addr(contract_address)
    if categories is not None:
        updated["categories"] = [c.strip() for c in categories]
    if provider_ids is not None:
        # Reject invalid provider id payloads: must be dict; nested "other" if present must be dict
        if "other" in provider_ids and provider_ids["other"] is not None and not isinstance(provider_ids["other"], dict):
            _log("error", meta={"error_code": "VALIDATION_ERROR"}, credential_id=credential_id)
            return _err("VALIDATION_ERROR", "provider_ids.other must be an object if provided.")
        updated["provider_ids"] = provider_ids
    if status is not None:
        updated["status"] = status

    updated["updated_at"] = now
    if not isinstance(updated.get("created_at"), str) or not updated.get("created_at"):
        updated["created_at"] = now

    # Enforce required fields on update (must remain valid)
    if not updated.get("name") or not isinstance(updated.get("name"), str):
        _log("error", meta={"error_code": "VALIDATION_ERROR"}, credential_id=credential_id)
        return _err("VALIDATION_ERROR", "name is required.")
    if updated.get("asset_type") not in ("cryptocurrency", "token", "defi_protocol"):
        _log("error", meta={"error_code": "VALIDATION_ERROR"}, credential_id=credential_id)
        return _err("VALIDATION_ERROR", "asset_type must map to one of: cryptocurrency, token, defi_protocol.")
    if not isinstance(updated.get("categories"), list):
        _log("error", meta={"error_code": "VALIDATION_ERROR"}, credential_id=credential_id)
        return _err("VALIDATION_ERROR", "categories must be an array.")
    if not isinstance(updated.get("provider_ids"), dict):
        _log("error", meta={"error_code": "VALIDATION_ERROR"}, credential_id=credential_id)
        return _err("VALIDATION_ERROR", "provider_ids must be an object.")
    if updated.get("status") not in ("active", "deprecated", "disabled"):
        _log("error", meta={"error_code": "VALIDATION_ERROR"}, credential_id=credential_id)
        return _err("VALIDATION_ERROR", "status must be one of: active, deprecated, disabled.")

    # Uniqueness checks (excluding self)
    cg = updated.get("provider_ids", {}).get("coingecko_coin_id") if isinstance(updated.get("provider_ids"), dict) else None
    if isinstance(cg, str) and cg.strip():
        cg0 = cg.strip()
        for a in assets_rows:
            if not isinstance(a, dict):
                continue
            if a.get("id") == updated["id"]:
                continue
            pid = a.get("provider_ids") if isinstance(a.get("provider_ids"), dict) else {}
            if pid.get("coingecko_coin_id") == cg0:
                _log("error", meta={"error_code": "CONFLICT"}, credential_id=credential_id)
                return _err("CONFLICT", "Provider id conflict: provider_ids.coingecko_coin_id must be unique.", field="provider_ids.coingecko_coin_id", value=cg0, conflicting_id=a.get("id"))

    if updated.get("contract_address"):
        ca0 = str(updated["contract_address"]).lower()
        ch0 = str(updated.get("primary_chain") or "").lower()
        for a in assets_rows:
            if not isinstance(a, dict):
                continue
            if a.get("id") == updated["id"]:
                continue
            if a.get("contract_address") and str(a.get("contract_address")).lower() == ca0 and str(a.get("primary_chain") or "").lower() == ch0:
                _log("error", meta={"error_code": "CONFLICT"}, credential_id=credential_id)
                return _err("CONFLICT", "Contract address conflict: (contract_address, primary_chain) must be unique.", field="contract_address", value=updated.get("contract_address"), conflicting_id=a.get("id"))

    if updated.get("symbol"):
        sy0 = str(updated["symbol"]).upper()
        for a in assets_rows:
            if not isinstance(a, dict):
                continue
            if a.get("id") == updated["id"]:
                continue
            if a.get("symbol") and str(a.get("symbol")).upper() == sy0 and a.get("asset_type") == updated.get("asset_type"):
                _log("error", meta={"error_code": "CONFLICT"}, credential_id=credential_id)
                return _err("CONFLICT", "Symbol conflict: (symbol, asset_type) must be unique.", field="symbol", value=sy0, conflicting_id=a.get("id"))

    # Persist update (no success without effect)
    changed = (updated != existing)
    if not changed:
        # idempotent update: still return stored record (realistic behavior) but must not lie about effect; it's ok because row existed.
        _log("ok", meta={"action": "noop", "asset_id": updated.get("id")}, credential_id=credential_id)
        return existing

    for i, a in enumerate(assets_rows):
        if isinstance(a, dict) and a.get("id") == existing.get("id"):
            assets_rows[i] = updated
            break

    if wrapper is not None:
        wrapper["rows"] = assets_rows
        _save("assets.json", wrapper)
    else:
        _save("assets.json", assets_rows)
    _log("ok", meta={"action": "updated", "asset_id": updated.get("id")}, credential_id=credential_id)
    return updated

def update_cache_entry_status(api_key, id, status, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0196000" if __import__("os").path.isdir("./environment_mix/0196000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "update_cache_entry_status"
    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _stable_hash(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            dt = v
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return None
        return None

    def _log(status_s, meta=None, credential_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        logs.append({
            "id": "req_" + _stable_hash(f"{endpoint}|{now.isoformat()}|{len(logs)}")[:24],
            "endpoint": endpoint,
            "tool_name": endpoint,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now.isoformat(),
            "credential_id": credential_id,
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    # Rate limit (global fallback)
    try:
        logs0 = _load("request_logs.json")
        if isinstance(logs0, list):
            now = _now_utc()
            cutoff = now - datetime.timedelta(seconds=60)
            recent = 0
            for r in reversed(logs0[-5000:]):
                ts = _parse_dt(r.get("timestamp"))
                if not ts:
                    continue
                if ts < cutoff:
                    break
                recent += 1
            if recent >= 240:
                _log("error", meta={"error_code": "RATE_LIMIT"})
                return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
    except Exception:
        pass

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "api_key is required.")
    if not isinstance(id, str) or not id.strip():
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "id must be a non-empty string.")
    if not isinstance(status, str) or status not in ("valid", "expired", "invalidated", "error"):
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "status must be one of: valid, expired, invalidated, error.")

    # Authenticate api_key (match plaintext value or id; no hash comparison)
    credential = None
    credential_id = None
    cred_files = ["api_keys.json", "credentials.json", "keys.json"]
    for fn in cred_files:
        rows = _load(fn)
        if isinstance(rows, dict) and "rows" in rows and isinstance(rows["rows"], list):
            rows = rows["rows"]
        if not isinstance(rows, list):
            continue
        for r in rows:
            if not isinstance(r, dict):
                continue
            if r.get("status") and str(r.get("status")) not in ("active", "valid", "enabled"):
                continue
            if api_key == r.get("id") or api_key == r.get("api_key") or api_key == r.get("key") or api_key == r.get("value"):
                credential = r
                credential_id = r.get("id")
                break
        if credential:
            break

    cred_store_exists = any(os.path.exists(os.path.join(_DB, fn)) for fn in cred_files)
    if cred_store_exists and not credential:
        _log("error", meta={"error_code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Invalid or revoked credential.")

    # Load cache entries
    entries = _load("cache_entries.json")
    wrapper = None
    if isinstance(entries, dict) and "rows" in entries and isinstance(entries["rows"], list):
        wrapper = entries
        rows = entries["rows"]
    elif isinstance(entries, list):
        rows = entries
    else:
        rows = []

    entry = None
    idx = None
    for i, e in enumerate(rows):
        if isinstance(e, dict) and e.get("id") == id:
            entry = e
            idx = i
            break
    if not entry:
        _log("error", meta={"error_code": "NOT_FOUND", "id": id}, credential_id=credential_id)
        return _err("NOT_FOUND", "Cache entry not found.", id=id)

    # Entitlement: without an explicit ownership model in schema/store, allow any authenticated key to manage.
    # (If future fields like workspace_id/scope exist, enforce here.)
    transitions = {
        "valid": {"expired", "invalidated", "error"},
        "expired": {"valid", "invalidated"},
        "invalidated": {"valid"},
        "error": {"valid", "invalidated"},
    }
    cur = entry.get("status")
    if cur not in transitions:
        _log("error", meta={"error_code": "CONFLICT", "current_status": cur}, credential_id=credential_id)
        return _err("CONFLICT", "Cache entry has unknown current status.", current_status=cur)
    if status != cur and status not in transitions[cur]:
        _log("error", meta={"error_code": "INVALID_TRANSITION", "from": cur, "to": status}, credential_id=credential_id)
        return _err("INVALID_TRANSITION", "Illegal cache status transition.", from_status=cur, to_status=status)

    # Idempotent: if same status, return entry
    if status == cur:
        _log("ok", meta={"action": "noop", "id": id, "status": status}, credential_id=credential_id)
        return entry

    updated = dict(entry)
    updated["status"] = status
    updated["updated_at"] = _now_utc().isoformat()
    rows[idx] = updated

    if wrapper is not None:
        wrapper["rows"] = rows
        _save("cache_entries.json", wrapper)
    else:
        _save("cache_entries.json", rows)

    _log("ok", meta={"action": "updated", "id": id, "from": cur, "to": status}, credential_id=credential_id)
    return updated

