    def _log(status_s, meta=None, credential_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_utc()
        logs.append({
            "id": "req_" + _stable_hash(f"{endpoint}|{now.isoformat()}|{len(logs)}")[:24],
            "endpoint": endpoint,
            "tool_name": endpoint,
