                recent += 1
            if recent >= 240:
                _log("error", meta={"error_code": "RATE_LIMIT"})
                return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.")
    except Exception:
        pass

    if not isinstance(api_key, str) or not api_key.strip():
        _log("error", meta={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "api_key is required.")

    # Authenticate by matching api_key to stored client-visible value or id (never compare hashes)
    credential = None
    cred_files = ["api_keys.json", "credentials.json", "keys.json"]
    for fn in cred_files:
        rows = _load(fn)
        if isinstance(rows, dict) and "rows" in rows and isinstance(rows["rows"], list):
            rows = rows["rows"]
        if not isinstance(rows, list):
            continue
        for r in rows:
            if not isinstance(r, dict):
                continue
            if r.get("status") and str(r.get("status")) not in ("active", "valid", "enabled"):
                continue
            if api_key == r.get("id") or api_key == r.get("api_key") or api_key == r.get("key") or api_key == r.get("value"):
